const { mesajGonder } = require("./anthropicMesaj");

const GENEL_BILGI_METNI = "=== BÖLÜM: SİGORTACILIĞA GİRİŞ (Tarihçe, Risk Kavramı, Risk Havuzu, Genel İlkeler, Kurumlar ve Meslek Grupları) ===\n\n**SİGORTACILIĞA GİRİŞ**\n\n**1. SİGORTACILIĞIN ORTAYA ÇIKIŞI VE TARİHSEL GELİŞİMİ**\n\n**SİGORTANIN ORTAYA ÇIKIŞI**\n\nİnsanlık tarihi boyunca insanlar üç temel riskle karşı karşıya\nkalmıştır:\n\n-   Mal kaybı (yangın, gemi batması, hırsızlık vb.)\n\n-   Gelir kaybı\n\n-   Can kaybı ve sağlık sorunları\n\nEskiden bir felaket yaşandığında kişi:\n\n-   Evini,\n\n-   Tarlasını,\n\n-   ticaret malını,\n\n-   geçim kaynağını\\\n    aynı anda kaybedebiliyordu.\n\nBu kayıp çoğu zaman telafi edilemiyor ve insanlar ekonomik olarak\ntamamen çöküyordu. Bu nedenle insanlar şu düşünceyi geliştirdi: \"Herkes\nküçük katkı yaparsa, zarara uğrayanın zararı birlikte karşılanabilir.\"\nİşte sigortacılığın temeli bu düşüncedir. Sigorta: **Zararın tek kişi\nyerine bir topluluk tarafından paylaşılmasıdır.**\n\n**1) İlk Sigortacılık Örnekleri (Antik Çağ)**\n\nSigortacılık resmi bir kurum olarak başlamadan önce **dayanışma\nsistemi** şeklinde ortaya çıktı.\n\n**Babil -- Hammurabi Kanunları (M.Ö. 1750)** Ticaret yapan kervanlarda:\n\n-   Mallar yolda yağmalanırsa,\n\n-   Kaybolursa,\n\n-   zarar diğer tüccarlar tarafından paylaşılırdı.\n\nBu sistem bugünkü risk paylaşımının ilk örneklerindendir.\n\n**Antik Çin**\n\nNehir taşımacılığı yapan tüccarlar:\n\n-   Mallarını tek gemiye yüklemek yerine\n\n-   birden fazla gemiye dağıtırdı.\n\nBir gemi batarsa herkes az zarar görürdü. Bu da riskin bölüştürülmesi\nyöntemidir.\n\n**Antik Roma**\n\nRoma'da cenaze ve yardım sandıkları vardı. Üyeler aidat öder, bir üye\nölünce cenaze masrafı karşılanırdı. Bu yapı günümüzdeki:\n\n-   Hayat sigortası\n\n-   Sosyal güvenlik\\\n    sistemlerinin ilk örnekleri sayılır.\n\n**2) Deniz Ticareti ve Modern Sigortanın Başlangıcı**\n\n> Orta Çağ'da ticaret deniz yoluyla hızla büyüdü. Ancak riskler büyüktü:\n\n-   Fırtınalar\n\n-   Korsan saldırıları\n\n-   Gemi batmaları\n\n-   Malların kaybı\n\nBu nedenle tüccarlar şu sistemi geliştirdi:\n\nBir grup yatırımcı:\n\n-   Sefer öncesi tüccardan para alır,\n\n-   Gemi batarsa zararı karşılar,\n\n-   Sefer başarılı olursa prim kendilerinde kalırdı.\n\nBu sistem **deniz sigortasının başlangıcıdır.**\n\n**3) Büyük Londra Yangını (1666) -- Dönüm Noktası**\n\nModern sigortacılığın gelişimindeki en önemli olaylardan biri **1666\nBüyük Londra Yangınıdır.** Yangında;\n\n-   13.000'den fazla ev yandı\n\n-   Şehrin büyük bölümü yok oldu\n\n-   On binlerce kişi evsiz kaldı\n\nBu felaketten sonra insanlar şunu fark etti: Büyük afetler karşısında\nbireysel güç yeterli değildir. Bunun sonucunda;\n\n-   İlk yangın sigorta şirketleri kuruldu.\n\n-   Ev ve işyerleri sigortalanmaya başladı.\n\n-   Modern sigortacılık doğdu.\n\n**4) Lloyd's ve Kurumsal Sigortacılık**\n\n17. yüzyılda Londra'da **Lloyd's Coffee House** isimli bir kahvehanede:\n\n-   Gemi sahipleri,\n\n-   tüccarlar,\n\n-   yatırımcılar\n\nbir araya gelip gemi risklerini paylaşmaya başladı. Zamanla burası:\n**Lloyd's of London** adıyla dünyanın en önemli sigorta piyasasına\ndönüştü.\n\n**5) Sanayi Devrimi ve Sigortanın Yayılması**\n\nSanayi Devrimi ile birlikte:\n\n-   Fabrikalar kuruldu,\n\n-   makineler arttı,\n\n-   iş kazaları çoğaldı,\n\n-   şehir nüfusu arttı.\n\nYeni riskler ortaya çıktı:\n\n-   İş kazaları\n\n-   Fabrika yangınları\n\n-   Çalışma hayatı riskleri\n\n-   Nakliye riskleri\n\nBunun sonucu:\n\n-   İş kazası sigortaları,\n\n-   sorumluluk sigortaları,\n\n-   mühendislik sigortaları gelişti.\n\n**6) 20. Yüzyıl ve Modern Sigortacılık**\n\n20. yüzyılda:\n\n-   Motorlu araçlar yaygınlaştı → Trafik sigortaları ortaya çıktı.\n\n-   Sağlık hizmetleri gelişti → Sağlık sigortaları büyüdü.\n\n-   Yaşam süresi uzadı → Emeklilik ve hayat sigortaları önem kazandı.\n\nSigorta artık sadece malı değil: geliri, sağlığı, geleceği, işletmeleri\nkoruyan bir sistem haline geldi.\n\n**Türkiye'de Sigortacılığın Gelişimi**\n\n**1870 Beyoğlu (Pera) Yangını ve Sigortacılığa Etkisi**\n\nSigortacılığın Osmanlı topraklarında gelişmesinde en önemli olaylardan\nbiri **5 Haziran 1870 Beyoğlu (Pera) Yangınıdır.** Beyoğlu dönemin en\nönemli ticaret merkezlerinden biri olduğu için zarar sadece bireysel\ndeğil, **ekonomik bir kriz niteliği taşıdı.** Bu olay, tıpkı Londra\nYangını gibi, coğrafyamızda sigorta ihtiyacının açık şekilde\nanlaşılmasına neden olmuştur ve Osmanlı topraklarında **modern\nsigortacılığın yayılmasının başlangıç noktalarından biri** kabul edilir.\n\n**Türkiye'de modern sigortacılık:**\n\n-   Osmanlı döneminde yabancı şirketlerle başladı.\n\n-   İlk dönemlerde daha çok yangın sigortaları yapıldı.\n\n-   Cumhuriyet döneminde yerli sigorta şirketleri kuruldu.\n\n-   Günümüzde ise sektör devlet denetimi altında güçlü bir yapıya\n    ulaştı.\n\n**2. SİGORTACILIKTA RİSK KAVRAMI**\n\n**RİSK NEDİR?**\n\nRisk, gelecekte meydana gelme ihtimali bulunan ve gerçekleştiğinde kişi\nveya kurumlara maddi veya manevi zarar verebilecek olaylardır. İnsan\nyaşamı ve ticari faaliyetler sürekli risk içerir. Çoğu zaman farkında\nolmasak bile günlük hayatımızda risklerle karşı karşıyayız.\n\n**Günlük Hayattan Risk Örnekleri**\n\n-   Trafik kazası geçirmek\n\n-   Aracın çalınması\n\n-   Evin yanması\n\n-   Depremde bina hasarı\n\n-   Sel baskını\n\n-   İş yerinde yangın çıkması\n\n-   İş kazası yaşanması\n\n-   Ciddi bir hastalık geçirilmesi\n\n-   Ameliyat gerektiren sağlık sorunu\n\n-   Hırsızlık\n\n-   Elektrik kaynaklı yangın\n\n-   Asansör kazası\n\n-   İş yerinde müşterinin kayıp düşmesi sonucu açılan dava\n\n-   Nakliye sırasında malın zarar görmesi\n\nSigortacılık sistemi bu risklerin ekonomik sonuçlarını hafifletmek için\nvardır.\n\n**RİSK TÜRLERİ;**\n\nRiskler temel olarak ikiye ayrılır.\n\n**1) Saf Risk (Sigortalanabilir Risk)**\n\nBu risklerde **sadece zarar ihtimali vardır**, kazanç ihtimali yoktur.\nYani olay gerçekleşirse zarar oluşur, gerçekleşmezse kazanç olmaz;\nsadece mevcut durum korunur.\n\n**Saf Risk Örnekleri;**\n\nTrafik kazası, Deprem, Yangın, Sel baskını, Hırsızlık, Hastalık, İş\nkazası, Maluliyet, Ölüm, Cam kırılması, Su baskını, Elektrik hasarı,\nMakine arızası, Nakliye hasarı\n\nSigorta sistemi bu riskleri güvence altına alır.\n\n**2) Spekülatif Risk (Sigortalanamaz Risk)**\n\nSpekülatif riskte hem **kazanç ihtimali hem zarar ihtimali vardır**. Bu\nriskler ticari veya yatırım kararlarından doğar ve sigorta kapsamına\ngirmez.\n\n**Spekülatif Risk Örnekleri;**\n\nDöviz yatırımı yapmak, Hisse senedi almak, Yeni iş kurmak, Ticari\nyatırım yapmak, Arsa yatırımı yapmak, Kripto para yatırımı, Altın alıp\nfiyat artışı beklemek, Yeni ürün üretimine girmek\n\nBu faaliyetlerde kişi:\n\n-   Kâr edebilir\n\n-   Zarar edebilir\n\nSigorta sistemi ***[yatırım riskini karşılamaz.]{.underline}***\n\n**RİSK YÖNETİMİ NEDİR?**\n\nİnsanlar risklerle farklı yöntemlerle mücadele eder.\n\n**1) Riskten Kaçınma**\n\nRiskli duruma hiç girmemek.\n\n-   Tehlikeli sporlardan uzak durmak\n\n-   Riskli bölgede iş kurmamak vb.\n\n**2) Riski Azaltma**\n\nRiskin zararını azaltmaya çalışmak.\n\n-   Yangın alarmı takmak\n\n-   Araçta güvenlik sistemi kullanmak\n\n-   İş yerinde iş güvenliği önlemleri almak vb.\n\n**3) Riski Üstlenme**\n\nKüçük zararları kendin karşılamak.\n\n-   Küçük çizikler için kasko kullanmamak\n\n-   Ufak sağlık giderlerini cebinden ödemek vb.\n\n> **4) Riski Devretme (Sigorta)**\n\nRiski sigorta şirketine devretmek.\n\n-   Kasko yaptırmak\n\n-   Sağlık sigortası yaptırmak\n\n-   İşyeri sigortası yaptırmak vb.\n\n**Risk Paylaşımı Mantığı**\n\nSigorta sisteminin temel mantığı: Birçok kişi küçük prim öder. Zarar\nyaşayan az sayıda kişinin kaybı bu havuzdan karşılanır.\n\n**Örneğin;**\n\nMilyonlarca araç sahibi her yıl prim öder. Bu araçların sadece küçük bir\nkısmı kaza yapar. Hasar ödemeleri ortak havuzdan karşılanır.\n\n**3. SİGORTACILIKTA HAVUZ NEDİR?**\n\n**RİSK HAVUZU**\n\nSigortacılık sisteminin temelinde **havuz mantığı** vardır. Sigorta\nşirketleri, poliçe sahiplerinden topladıkları primleri tek bir fonda\ntoplar. Bu fon, gerçekleşen hasarların ödenmesinde kullanılır. Bu\nsisteme **risk havuzu** denir.\n\nYani sistem şu mantıkla çalışır:\n\nÇok sayıda kişi küçük miktarda prim öder. Zarar yaşayan az sayıdaki\nkişinin kaybı bu ortak fondan karşılanır. Bu sayede tek bir kişinin\nbüyük zararı herkes tarafından paylaşılmış olur.\n\n**Havuz Mantığını Günlük Örnekle Anlamak**\n\nBir apartmanda 20 daire olduğunu düşünelim. Her daire sahibi yılda 1.000\nTL yangın güvenlik fonuna katkı sağlasın. Toplanan para: 20 × 1.000 =\n20.000 TL Yıl içinde sadece bir dairede yangın çıkarsa ve zarar 20.000\nTL ise, zarar ortak fondan karşılanmış olur. Yani herkes küçük katkı\nyapmış, zarar gören kişi büyük zarardan korunmuştur.\n\nSigorta sistemi bunun milyonlarca kişi için yapılan profesyonel halidir.\n\n**Gerçek Hayatta Havuz Nasıl Çalışır?**\n\nÖrneğin; 10.000 araç sahibi trafik sigortası yaptırıyor.Her biri\nortalama 5.000 TL prim ödüyor.\n\nToplanan prim: 10.000 × 5.000 = 50 milyon TL Bu araçların hepsi kaza\nyapmaz. Sadece belirli bir kısmı hasar alır. Hasar ödemeleri bu ortak\nfondan yapılır.\n\n**Havuz Sisteminin Sağladığı Avantajlar**\n\n**1) Büyük zararlar paylaşılır**\n\nTek kişinin büyük kaybı herkes arasında bölüşülür.\n\n**2) Hayat ekonomik olarak güvenli hale gelir**\n\nKişiler tek bir olay yüzünden iflas etmez.\n\n**3) Ticari hayat devam eder**\n\nİşletmeler hasar sonrası faaliyetlerine devam edebilir.\n\n**Havuzun Doğru Çalışması Neye Bağlıdır?**\n\nHavuz sistemi doğru çalışabilmek için:\n\n-   Çok sayıda sigortalı olmalı,\n\n-   Riskler doğru hesaplanmalı,\n\n-   Primler doğru belirlenmeli,\n\n-   Hasarlar doğru yönetilmelidir.\n\nBu nedenle aktüerler ve teknik ekipler önemlidir.\n\n**Havuzu Bozan Durumlar**\n\nBazı davranışlar havuz sistemini bozar.\n\n**1) Sigorta Dolandırıcılığı**\n\nGerçek olmayan hasar bildirimleri.\n\n**2) Küçük Hasarların Sürekli Kullanılması**\n\nSigortayı bakım servisi gibi kullanmak.\n\n**3) Yanlış Risk Kabulü**\n\nÇok riskli kişilerin doğru fiyatlandırılmaması.\n\nSonuçta herkesin primi yükselir.\n\n**Türkiye'de Özel Sigorta Havuzları da Vardır**\n\nBazı büyük riskler için devlet destekli havuzlar kurulmuştur.\n\n**DASK -- Zorunlu Deprem Sigortası**\n\nTürkiye'de deprem riski ortak havuz sistemiyle yönetilir.\n\n**Tarım Sigortaları Havuzu (TARSİM)**\n\nÇiftçilerin zararları havuz sistemiyle karşılanır.\n\n**Önemli Sonuç**\n\nSigorta sistemi:\n\n\"Ben prim ödüyorum ama hiç kullanmıyorum\" mantığıyla değil,\"Ben büyük\nbir riske karşı korunuyorum\" mantığıyla değerlendirilmelidir.\n\n-   Sigortanın amacı hasar etmek değil, *[**zararın ekonomik yıkımını\n    önlemektir**.]{.underline}*\n\n-   Sigorta satış ürünü değil, ***[ekonomik güvenlik\n    sistemidir.]{.underline}***\n\n-   Sigorta lüks değil, ***[felaketlerden doğmuş bir\n    ihtiyaçtır.]{.underline}***\n\n-   Sigortacı poliçe değil, ***[güvence satar.]{.underline}***\n\n**SİGORTANIN KONUSU ZARAR DEĞİL, RİSKTİR**\n\nSigortacılıkta en önemli temel kurallardan biri şudur: **Gerçekleşmiş\nbir olay artık risk değildir.** Sigorta sistemi **henüz gerçekleşmemiş,\ngerçekleşme ihtimali bulunan olayları** güvence altına alır. Eğer zarar\nmeydana geldikten sonra sigorta yapılmak istenirse, bu artık sigortanın\nkonusu olmaz. Çünkü sigorta ***[gelecekte oluşabilecek belirsiz riskleri\nkapsar.]{.underline}***\n\n**Örneğin;**\n\n-   Aracınız kaza yaptıktan sonra kasko yaptırıp hasarın ödenmesini\n    isteyemezsiniz.\n\n-   Ev yandıktan sonra konut sigortası yapılamaz.\n\n-   Sağlık problemi başladıktan sonra özel sağlık sigortası geçmiş\n    hastalığı karşılamaz.\n\n-   İş yeri soyulduktan sonra işyeri sigortası yaptırılamaz.\n\nOlay meydana geldikten sonra artık risk ortadan kalkmıştır; zarar\nkesinleşmiştir.\n\n**[SİGORTA ŞİRKETLERİ SÜPERMARKET DEĞİLDİR]{.underline}**\n\nSigortacılıkta en sık karşılaşılan yanlış algılardan biri şudur: Birçok\nkişi sigortayı, zarar oluştuktan sonra gidip satın alınabilecek bir ürün\ngibi düşünür. Oysa sigortanın çalışma mantığı tamamen farklıdır.\n\nSigorta sistemi, **zarar meydana geldikten sonra çözüm üretmek için\ndeğil, zarar meydana gelmeden önce finansal güvence sağlamak için\nvardır.**\n\nSigorta şirketleri:\n\n> ✔ Gerçekleşmiş zararı satın almaz\\\n> ✔ Hazır oluşmuş hasarı ödemez\\\n> ✔ Geçmiş zararı karşılamaz\n\nSigorta şirketleri **sadece riski satın alır**. Yani: Henüz\ngerçekleşmemiş bir zararın finansal sorumluluğunu, belirli bir prim\nkarşılığında üstlenir.\n\n**Basit Mantık**\n\nEğer insanlar hasar olduktan sonra sigorta yaptırabilseydi:\n\n-   Kimse önceden sigorta yaptırmazdı,\n\n-   Sadece zarar yaşayanlar sigorta alırdı,\n\n-   Sistem sürdürülemez hale gelirdi.\n\nBu nedenle sigorta sistemi yalnızca **belirsiz riskleri** kapsar.\n\n**4. SİGORTACILIĞIN GENEL İLKELERİ**\n\nSigortacılık belirli kurallar üzerine kuruludur.\n\n**Azami İyi Niyet İlkesi**\n\nSigorta yaptıran kişi doğru bilgi vermek zorundadır.\n\nÖrneğin;\n\n-   Ağır hasarlı aracı gizlemek\n\n-   Sağlık geçmişini saklamak\n\n-   Aracın ticari kullanımını gizlemek\n\nYanlış bilgi poliçeyi geçersiz yapabilir.\n\n**Sigortalanabilir Menfaat İlkesi**\n\nKişinin sigortalanan şeyle maddi ilişkisi olmalıdır.\n\nÖrneğin;\n\n-   Kendi evinizi sigortalayabilirsiniz.\n\n-   Komşunun evini sigortalayamazsınız.\n\n**Tazminat İlkesi**\n\n> Amaç zarar kadar ödeme yapmaktır. Sigortadan kazanç sağlanamaz.\n>\n> Örneğin;\\\n> 200.000 TL değerindeki araca 400.000 TL ödeme yapılmaz.\n\n**Halefiyet İlkesi**\n\nSigorta şirketi zarara sebep olan kişiye dönebilir.\n\n> Örneğin;\\\n> Kazaya sebep olan kişi sigorta şirketine ödeme yapar.\n\n**Yakın Sebep İlkesi**\n\nHasarın gerçek nedeni belirlenir.\n\n> Örneğin;\\\n> Deprem sonrası çıkan yangının asıl sebebi deprem olabilir.\n\n**5. SİGORTACILIKTA KURUMLAR VE SEKTÖRDEKİ MESLEK GRUPLARI**\n\nSigortacılık sektörü yalnızca poliçe satılan bir alan değildir.\nArkasında çok geniş bir yapı ve birçok farklı meslek bulunmaktadır.\nSigorta sektörü, finans sektörünün önemli bir parçasıdır ve birçok\nkurumun birlikte çalışmasıyla işler.\n\n**Sigorta Sektörünün Temel Kurumları**\n\n**1) Sigorta ve Emeklilik Şirketleri**\n\nSigorta şirketleri faaliyet alanlarına göre **iki ana gruba ayrılır:**\n\n**1) Hayat ve Emeklilik Şirketleri**\n\n**2) Hayat Dışı (Elementer) Sigorta Şirketleri**\n\nBu ayrım sektörün temel yapısını oluşturur.\n\n**1. Hayat ve Emeklilik Şirketleri**\n\nBu şirketler insan hayatı, sağlık ve uzun vadeli birikim odaklı ürünler\nsunar.\n\nFaaliyet alanları:\n\n-   Hayat sigortaları\n\n-   Bireysel Emeklilik Sistemi (BES)\n\n-   Ferdi kaza sigortaları\n\n-   Uzun vadeli birikimli sigortalar\n\n-   Kredi bağlantılı hayat sigortaları\n\nBu şirketler hem **risk teminatı** hem de **uzun vadeli birikim\nsistemi** sunar.\n\nÖrnek ürünler:\n\n-   Kredi hayat sigortası\n\n-   Birikimli hayat poliçeleri\n\n-   BES planları\n\n-   Çocuk eğitim planları\n\n**2. Hayat Dışı (Elementer) Sigorta Şirketleri**\n\nGünlük hayatta en sık karşılaşılan sigortalar bu gruba girer.\n\nFaaliyet alanları:\n\n-   Trafik sigortası\n\n-   Kasko\n\n-   Konut sigortası\n\n-   İşyeri sigortası\n\n-   Sağlık sigortaları\n\n-   Nakliyat sigortaları\n\n-   Sorumluluk sigortaları\n\n-   Mühendislik sigortaları\n\n-   Tarım sigortaları\n\nBu şirketler genellikle **yıllık poliçeler** üzerinden çalışır.\n\nSigorta şirketleri, sigorta poliçelerini düzenleyen ve riskleri üstlenen\nkuruluşlardır. Sigortalılar prim öder, risk gerçekleşirse sigorta\nşirketi hasarı karşılar.\n\nSigorta şirketlerinin temel görevleri:\n\n-   Poliçe düzenlemek\n\n-   Risk analizi yapmak\n\n-   Prim belirlemek\n\n-   Hasar gerçekleştiğinde tazminat ödemek\n\n-   Riskleri reasürans yoluyla dağıtmak\n\n-   BES ve hayat sigortası ürünlerini yönetmek\n\n**2) Sigorta Acenteleri**\n\nAcenteler, sigorta şirketleri adına poliçe satış ve işlemlerini yapan\nkuruluşlardır.\n\nGenellikle bir veya birkaç şirketle çalışırlar.\n\nGörevleri:\n\n-   Müşteri ihtiyaçlarını analiz etmek\n\n-   Uygun poliçeyi sunmak\n\n-   Poliçe düzenlemek\n\n-   Satış sonrası hizmet vermek\n\n-   Hasar süreçlerinde müşteriye destek olmak\n\nAcenteler sigorta şirketinin temsilcisidir.\n\n**3) Sigorta Brokerleri**\n\nBrokerler sigorta şirketi adına değil, müşteri adına çalışır. Amaç\nmüşteriye en uygun sigorta çözümünü bulmaktır.\n\nGörevleri:\n\n-   Farklı şirketlerden teklif almak\n\n-   Karşılaştırma yapmak\n\n-   Müşteriye en uygun poliçeyi sunmak\n\n-   Büyük risklerde danışmanlık yapmak\n\nBrokerler özellikle:\n\n-   Büyük işletmeler\n\n-   Sanayi kuruluşları\n\n-   Kurumsal müşterilerle çalışır.\n\n**4) Reasürans Şirketleri**\n\nSigorta şirketleri de büyük riskleri tek başına taşımak istemez. Bu\nnedenle risklerinin bir kısmını reasürans şirketlerine devrederler.\n\n> Örnek: Büyük bir fabrikanın hasarı milyonlarca TL olabilir. Bu risk\n> paylaşılır.\n>\n> Amaç: Sigorta şirketinin mali yapısını korumaktır.\n\n**Devlet ve Denetleyici Kurumlar**\n\nTürkiye'de sigorta sektörü devlet tarafından denetlenir.\n\nAna kurum:\n\n**1) SEDDK** (Sigortacılık ve Özel Emeklilik Düzenleme ve Denetleme\nKurumu)\n\nSEDDK, sigorta ve bireysel emeklilik sektörünü düzenlemek ve denetlemek\namacıyla 2019 yılında kurulmuş, 2020 yılında aktif olarak faaliyet\ngöstermeye başlamıştır. Sigorta sektörünün en üst düzenleyici ve\ndenetleyici kurumudur.\n\nGörevleri:\n\n-   Sigorta şirketlerini denetlemek\n\n-   Mevzuatı düzenlemek\n\n-   Sigortalı haklarını korumak\n\n-   Piyasa düzenini sağlamak\n\n**2) Türkiye Sigorta Birliği (TSB)**\n\nSigorta şirketlerinin meslek örgütüdür.\n\nGörevleri:\n\n-   Sektör istatistiklerini toplamak\n\n-   ortak uygulamalar geliştirmek\n\n-   sektörü temsil etmek\n\n**3) DASK (Doğal Afet Sigortaları Kurumu)**\n\nZorunlu deprem sigortasını yöneten kurumdur. DASK, kamu destekli bir\nsigorta havuzu sistemidir.\n\nAmaç:\n\n-   Deprem riskini ülke genelinde paylaşmak\n\n-   deprem sonrası ekonomik yükü azaltmak\n\n**4) SBM (Sigorta Bilgi ve Gözetim Merkezi)**\n\nSigorta sektörünün veri merkezidir.\n\nGörevleri:\n\n-   Trafik ve kasko hasar kayıtlarını tutmak\n\n-   TRAMER sistemini yönetmek\n\n-   poliçe ve hasar bilgilerini toplamak\n\nAraç hasar geçmişi sorguları buradan yapılır.\n\n> **5) Emeklilik Gözetim Merkezi (EGM)**\n\nBireysel Emeklilik Sistemi\\'nin merkezi kayıt ve gözetim kuruluşudur.\n\nGörevleri:\n\n-   BES sözleşmelerini kayıt altında tutmak\n\n-   devlet katkısı süreçlerini izlemek\n\n-   katılımcı sistem hareketlerini takip etmek\n\nKatılımcı şirket değiştirse bile kayıtlar EGM'de korunur.\n\n**6) Takasbank**\n\nSigorta şirketi değildir; finansal altyapı sağlar.\n\nÖzellikle BES fonlarının saklanmasında kritik rol oynar.\n\nFonlar:\n\n-   emeklilik şirketinde değil,\n\n-   Takasbank'ta saklanır.\n\nAmaç katılımcı birikimini şirket riskine karşı korumaktır.\n\n**7) SEGEM (Sigortacılık Eğitim Merkezi)**\n\nSigorta sektöründe çalışacak kişilerin eğitim ve sınav süreçlerini\nyöneten kurumdur.\n\nSigortacılık faaliyetinde bulunabilmek için SEGEM belgesi gerekir.\nSEGEM, sektörde mesleki yeterlilik sağlar.\n\n**8) Sigorta Tahkim Komisyonu**\n\nSigorta şirketi ile sigortalı arasında uyuşmazlık oluştuğunda başvurulan\nalternatif çözüm merkezidir. Mahkemeye gitmeden önce hızlı çözüm sağlar.\n\nAvantajları:\n\n-   Daha hızlı sonuç\n\n-   Daha düşük maliyet\n\n-   Uzman hakemler tarafından karar verilmesi\n\nSigortalı haklarını koruyan önemli bir mekanizmadır.\n\n**SİGORTA SEKTÖRÜNDEKİ MESLEK GRUPLARI**\n\nSigorta sektörü yalnızca satış personelinden oluşmaz. Çok sayıda farklı\nmeslek vardır.\n\n**1) Sigorta Danışmanı / Satış Temsilcisi**\n\nMüşteriye sigorta ürünlerini anlatır ve poliçe satışını gerçekleştirir.\n\nGörevleri:\n\n-   Müşteri ihtiyacını anlamak\n\n-   Doğru ürünü önermek\n\n-   Teklif hazırlamak\n\n-   Poliçe sürecini yürütmek\n\n**2) Underwriting**\n\nRisk değerlendirmesi yapan uzmanlardır.\n\nGörevleri:\n\n-   Riskin kabul edilip edilmeyeceğini belirlemek\n\n-   Prim hesaplamak\n\n-   Özel şartlar belirlemek\n\nYanlış risk kabulü şirkete zarar doğurabilir.\n\n**3) Hasar Uzmanları**\n\nHasar dosyalarını inceleyen kişilerdir.\n\nGörevleri:\n\n-   Hasar evraklarını incelemek\n\n-   Ödeme kararını vermek\n\n-   Hasar sürecini yönetmek\n\n**4) Sigorta Eksperleri**\n\nHasarın büyüklüğünü yerinde inceleyen uzmanlardır.\n\nGörevleri:\n\n-   Hasarı incelemek\n\n-   zarar miktarını belirlemek\n\n-   rapor hazırlamak\n\nÖdeme eksper raporuna göre yapılır. Bağımsız çalışırlar.\n\n**5) Aktüerler**\n\nSigortacılığın matematik ve risk hesaplama uzmanlarıdır.\n\nGörevleri:\n\n-   Risk ve hasar olasılıklarını hesaplamak\n\n-   Prim fiyatlarını belirlemek\n\n-   Uzun vadeli mali hesaplar yapmak\n\nSigorta fiyatlamasının temelini oluştururlar.\n\n**6) Hasar Danışmanları ve Hukuk Birimleri**\n\nUyuşmazlık durumlarında süreci yönetirler.\n\n**7) Operasyon ve Müşteri Hizmetleri Personeli**\n\nPoliçe işlemleri ve müşteri süreçlerini yürütürler.\n\n=== BÖLÜM: SİGORTACILIKTA TEMEL KAVRAMLAR VE TERİMLER SÖZLÜĞÜ (Sigorta, Risk, Poliçe, Sigortalı, Sigorta Ettiren, Lehtar, Prim, Teminat, Muafiyet, Hasar, Ekspertiz, Tazminat, Hasarsızlık İndirimi, Zeyilname, Reasürans, Eksik/Aşkın Sigorta, Halefiyet vb.) ===\n\n**SİGORTACILIKTA TEMEL KAVRAMLAR**\n\n**1) Sigorta Nedir?**\n\nSigorta, gelecekte gerçekleşmesi muhtemel risklerin doğuracağı maddi\nzararların, belirli bir prim karşılığında sigorta şirketi tarafından\nkarşılanması sistemidir.\n\nBaşka bir ifadeyle:\n\nBir kişinin tek başına karşılayamayacağı büyük zararlar, birçok kişinin\nödediği küçük primlerle oluşturulan havuzdan karşılanır.\n\n**2) Risk (Riziko)**\n\nRisk, gerçekleşmesi halinde maddi kayba yol açabilecek belirsiz olaydır.\n\n> Örnek riskler:\\\n> • Yangın\\\n> • Deprem\\\n> • Trafik kazası\\\n> • Hastalık\\\n> • Hırsızlık\n>\n> Önemli nokta:\n\nRisk gerçekleşmeden önce sigorta yapılmalıdır. Sigorta geçmişte olmuş\nbir zararı değil, gelecekte olabilecek riski teminat altına alır.\n\n**3) Poliçe**\n\nPoliçe, sigorta sözleşmesini gösteren resmi belgedir.\n\n> Poliçede:\\\n> • Sigortalı bilgileri\\\n> • Teminatlar\\\n> • Teminat limitleri\\\n> • Sigorta süresi\\\n> • Prim tutarı\\\n> • Özel şartlar\n\nyer alır.\n\nPoliçe sigorta sözleşmesinin yazılı halidir.\n\n**4) Sigortalı**\n\nSigorta güvencesi altında bulunan kişi veya kurumdur.\n\n> Örnek:\\\n> Araç sigortasında araç sahibi sigortalıdır.\n\n**5) Sigorta Ettiren (Sponsor)**\n\nPoliçeyi yaptıran ve primi ödeyen kişidir.\n\nBazı durumlarda sigorta ettiren ile sigortalı farklı olabilir.\n\n> Örnek:\\\n> Bir baba çocuğu adına sağlık sigortası yaptırabilir.\n\n**6) Lehtar**\n\nSigorta tazminatını almaya hak kazanan kişidir.\n\nÖzellikle hayat sigortalarında önemlidir.\n\n> Örnek:\\\n> Sigortalının vefatı halinde ödeme eşine veya çocuklarına yapılabilir.\n\n**7) Prim**\n\nSigortalının, aldığı güvence karşılığında sigorta şirketine ödediği\nücrettir.\n\n> Prim tutarı şu unsurlara göre belirlenir:\\\n> • Riskin büyüklüğü\\\n> • Teminat kapsamı\\\n> • Sigortalının özellikleri\\\n> • Hasar geçmişi\n\nRisk arttıkça prim yükselir.\n\n**8) Teminat**\n\nSigorta poliçesinin güvence altına aldığı risklerdir.\n\n> Örnek:\\\n> Kasko poliçesinde:\\\n> • Çarpma\\\n> • Yanma\\\n> • Hırsızlık\n\nbirer teminattır.\n\n**9) Teminat Limiti**\n\nSigorta şirketinin ödeyeceği en yüksek tutardır.\n\n> Örnek:\\\n> Teminat limiti 500.000 TL ise, hasar daha büyük olsa bile ödeme bu\n> tutarı geçmez.\n\n**10) Muafiyet**\n\nHasarın belirli bir kısmının sigortalı tarafından karşılanmasıdır.\n\nAmaç küçük hasarların poliçeye yansımamasıdır.\n\n> Örnek:\\\n> 10.000 TL hasarda 2.000 TL muafiyet varsa,\\\n> sigorta şirketi 8.000 TL öder.\n\n**11) Hasar**\n\nSigorta kapsamında güvence altına alınmış riskin gerçekleşmesi sonucu\noluşan zarardır.\n\n> Örnek:\\\n> Trafik kazası sonrası araç hasarı.\n\n**12) Ekspertiz**\n\nHasarın boyutunu belirlemek için yapılan inceleme sürecidir.\n\n> Eksper:\\\n> • Hasarın nasıl oluştuğunu,\\\n> • Ne kadar zarar oluştuğunu,\\\n> • Teminat kapsamında olup olmadığını inceler.\n\n**13) Tazminat**\n\nHasar gerçekleştiğinde sigorta şirketinin yaptığı ödemedir.\n\nAmaç sigortalıyı zarar öncesi mali durumuna geri getirmektir.\n\nSigorta kazanç sağlama aracı değildir.\n\n**14) Hasarsızlık İndirimi**\n\nSigortalının belirli süre hasar yapmaması halinde uygulanan prim\nindirimi sistemidir.\n\n> En yaygın kullanım alanı:\\\n> Kasko sigortasıdır.\n\n**15) Zeyilname**\n\nPoliçede sonradan yapılan değişiklikleri gösteren ek belgedir.\n\n> Örnek:\\\n> • Araç değişikliği\\\n> • Adres değişikliği\\\n> • Teminat artırımı\n\n**16) Reasürans**\n\nSigorta şirketlerinin üstlendikleri riskin bir kısmını başka sigorta\nşirketlerine devretmesidir.\n\nAmaç büyük zararların şirketi zor durumda bırakmasını önlemektir.\n\n**17) Sigorta Bedeli**\n\nSigortalanan malın poliçede belirtilen değeridir.\n\nDoğru belirlenmesi çok önemlidir.\n\n**18) Eksik Sigorta**\n\nSigorta bedeli gerçek değerden düşük belirlenmişse oluşur.\n\nBu durumda hasarın tamamı ödenmez.\n\n**19) Aşkın Sigorta**\n\nMalın gerçek değerinden daha yüksek tutarda sigortalanmasıdır.\n\nSigorta kazanç sağlamaz; gerçek zarar kadar ödeme yapılır.\n\n**20) Halefiyet Hakkı (Rücu)**\n\nSigorta şirketi zararı ödedikten sonra kusurlu kişiye rücu edebilir.\n\n=== BÖLÜM: HAYAT DIŞI (ELEMENTER) SİGORTALAR (Yangın, Doğal Afet/DASK, Kara Araçları/Trafik/Kasko, Genel Zararlar, Tarım, Sorumluluk, Mesleki Sorumluluk, Finansal Kayıplar, Siber Risk, Sağlık Sigortaları) ===\n\n**HAYAT DIŞI SİGORTALAR**\n\nHayat dışı sigortalar, günlük yaşamda karşılaşabileceğimiz maddi\nzararları güvence altına alan sigorta türleridir.\n\nBu sigortalar insanların:\n\n-   araçlarını,\n\n-   evlerini,\n\n-   işyerlerini,\n\n-   işletmelerini,\n\n-   sorumluluklarını,\n\n-   sağlık giderlerini,\n\n-   gelirlerini\n\nkoruma altına alır.\n\nBu bölümde hayat dışı sigortaların temel branşları ele alınacaktır.\n\n**1. FİNANS SİSTEMİNDE SİGORTACILIĞIN YERİ**\n\nSigorta sistemi yalnızca bireyleri değil, aynı zamanda tüm ekonomik\nsistemi koruyan bir güvenlik mekanizmasıdır. Günümüzde sigortacılık,\nbankacılık ve sermaye piyasaları ile birlikte finans sisteminin üç temel\nayağından biri olarak kabul edilir.\n\nEkonomik faaliyetler her zaman risk içerir. Fabrikalar üretim yaparken\nyangın riski taşır, lojistik firmaları taşımacılık sırasında kaza\nriskiyle karşı karşıyadır, işletmeler doğal afetlerden etkilenebilir. Bu\nriskler gerçekleştiğinde sadece işletme sahibi değil, çalışanlar,\ntedarikçiler ve müşteriler de zarar görür.\n\nÖrneğin:\n\n-   Büyük bir fabrikanın yanması yüzlerce çalışanın işsiz kalmasına,\n\n-   üretimin durmasına,\n\n-   tedarik zincirinin bozulmasına,\n\n-   piyasada ürün kıtlığı oluşmasına neden olabilir.\n\nSigorta sistemi bu noktada devreye girerek zararın finansal yükünü\nişletmenin üzerinden alır ve faaliyetlerin yeniden başlamasını sağlar.\n\n> Bu sayede:\\\n> • işletmeler faaliyetlerine devam eder,\\\n> • üretim kesintiye uğramaz,\\\n> • çalışanların iş kaybı önlenir,\\\n> • ekonomik düzen korunur,\\\n> • piyasada güven ortamı sürer.\n\n**Sigorta Ekonomide Neden Kritik Bir Rol Oynar?**\n\nSigortasız bir ekonomide büyük bir afet veya yangın sonrası işletmeler\nçoğu zaman tekrar ayağa kalkamaz. Bu durum domino etkisi yaratır:\n\n-   İşsizlik artar,\n\n-   üretim azalır,\n\n-   vergi gelirleri düşer,\n\n-   piyasada güven kaybolur,\n\n-   yatırımcılar risk almaktan kaçınır.\n\nSigorta ise ekonomiye şu katkıları sağlar:\n\n> **1) Ekonomik İstikrar Sağlar**\n\nHasar gören işletmeler sigorta tazminatı sayesinde yeniden faaliyete\ngeçebilir.\n\n**2) Yatırım Yapmayı Kolaylaştırır**\n\nYatırımcılar risklerini sigorta ile güvence altına aldıkları için daha\nrahat yatırım yapar.\n\n**3) Kredi Sistemini Destekler**\n\nBankalar kredi verdikleri varlıkların sigortalı olmasını ister. Böylece\nkredi sistemi daha güvenli çalışır.\n\n**4) Tasarrufları Ekonomiye Kazandırır**\n\nSigorta şirketleri topladıkları primleri:\n\n-   devlet tahvilleri,\n\n-   hisse senetleri,\n\n-   fonlar,\n\n-   altyapı yatırımları\\\n    gibi alanlarda değerlendirir.\n\nBu da ekonomiye uzun vadeli finansman sağlar.\n\n**Sigorta, Ekonomik Şokları Yumuşatır**\n\nDeprem, sel, büyük yangın gibi afetlerde milyarlarca liralık zarar\noluşabilir. Eğer bu zararlar sigorta sistemiyle dağıtılmazsa ekonomik\nkrizler ortaya çıkabilir.\n\nSigorta sistemi:\n\n-   zararı birçok sigortalı arasında paylaştırır,\n\n-   ekonomik şokların etkisini azaltır,\n\n-   piyasanın çökmesini önler.\n\n**Sigorta Olmayan Bir Ekonomiyi Düşünelim**\n\nSigortasız bir ortamda:\n\n-   Fabrika yanarsa üretim biter.\n\n-   İşletme kapanır.\n\n-   Çalışanlar işsiz kalır.\n\n-   Tedarikçiler zarar görür.\n\n-   Banka verdiği krediyi tahsil edemez.\n\nYani tek bir hasar tüm ekonomiyi etkileyebilir. Sigorta sistemi bu\nzincirleme etkiyi kırar.\n\n**2. YANGIN SİGORTALARI**\n\nYangın sigortaları, sigortacılığın en eski ve en temel branşlarından\nbiridir. Temel amacı, yangın sonucu oluşabilecek maddi zararların\nfinansal yükünü sigortalının üzerinden alarak ekonomik kayıpları telafi\netmektir.\n\nYangın sadece binayı değil, bina içindeki tüm mal varlığını da\netkileyebilir. Bu nedenle yangın sigortası hem konutlar hem işyerleri\niçin kritik bir güvence sağlar.\n\n**Yangın Sigortası Neleri Korur?**\n\nYangın sigortası yalnızca binayı değil, aşağıdaki unsurları da güvence\naltına alabilir:\n\n> • Binanın kendisi\\\n> • Demirbaşlar\\\n> • Makine ve ekipmanlar\\\n> • Ofis eşyaları\\\n> • Stok ve emtialar\\\n> • Elektronik cihazlar\\\n> • Dekorasyon giderleri\n\nÖrneğin:\n\n-   Bir restoranın mutfağında çıkan yangın tüm ekipmanları kullanılamaz\n    hale getirebilir.\n\n-   Bir tekstil deposunda çıkan yangın milyonlarca liralık ürünün yok\n    olmasına neden olabilir.\n\n-   Bir ofiste çıkan yangın, bilgisayarlar ve evrakların tamamen zarar\n    görmesine yol açabilir.\n\n**Temel Teminatlar**\n\n> Standart yangın poliçelerinde üç ana risk güvence altındadır:\n\n**1) Yangın**\n\nKontrol dışı başlayan ve yayılan ateşin neden olduğu zararlar.\n\n> Örnek:\\\n> Elektrik kontağından çıkan yangın sonucu binanın yanması.\n\n**2) Yıldırım**\n\nYıldırım düşmesi sonucu oluşan maddi zararlar.\n\n> Örnek:\\\n> Yıldırım düşmesi sonucu binanın çatısının yanması.\n\n**3) İnfilak (Patlama)**\n\nGaz sıkışması veya benzeri nedenlerle meydana gelen patlamaların verdiği\nzararlar.\n\n> Örnek:\\\n> Doğalgaz patlaması sonucu oluşan hasarlar.\n\n**Ek Teminatlarla Kapsam Genişletilebilir**\n\nYangın poliçeleri genellikle genişletilmiş paketlerle satılır. Ek\nteminatlarla birçok farklı risk güvence altına alınabilir.\n\n**Duman Zararları**\n\nYangın sonucu oluşan dumanın verdiği zararlar.\n\n> Örnek:\\\n> Yan dairede çıkan yangının dumanı eşyaları kullanılmaz hale getirir.\n\n**Fırtına**\n\nŞiddetli rüzgârın verdiği zararlar.\n\n> Örnek:\\\n> Fırtınada çatının uçması.\n\n**Sel ve Su Baskını**\n\nYoğun yağış veya taşkın sonucu oluşan zararlar.\n\n> Örnek:\\\n> Bodrum kattaki işyerinin su altında kalması.\n\n**Yer Kayması**\n\nToprak hareketleri sonucu oluşan zararlar.\n\n**Grev, Lokavt, Halk Hareketleri**\n\nToplumsal olaylar sırasında meydana gelen zararlar.\n\n**Terör Teminatı**\n\nTerör olaylarının neden olduğu maddi zararlar.\n\n**İşyerleri İçin Ek Güvenceler**\n\nİşyerlerinde zarar sadece fiziki hasarla sınırlı kalmaz. Faaliyetin\ndurması daha büyük kayıplar doğurabilir.\n\nBu nedenle işyerleri için ek teminatlar önemlidir.\n\n**İş Durması (Kâr Kaybı) Teminatı**\n\nYangın sonrası işletme faaliyet gösteremezse oluşan gelir kaybını\nkarşılar.\n\n> Örnek:\\\n> Yangın sonrası restoranın 3 ay kapalı kalması.\n\n**Kira Kaybı Teminatı**\n\nKiraya verilen bir işyerinde hasar sonrası kira geliri kaybını karşılar.\n\n**Yangın Sigortasında En Sık Yapılan Hata**\n\nEn yaygın hata, bina veya içindeki malların **eksik bedelle\nsigortalanmasıdır**.\n\nÖrneğin:\\\nGerçek değeri 10 milyon TL olan bir işletme 5 milyon TL'ye\nsigortalanırsa, hasarın sadece yarısı karşılanabilir.\n\nBu durum **eksik sigorta** problemine yol açar.\n\n**Yangın Sigortası Satışında Danışmanın Rolü**\n\nİyi bir sigorta danışmanı sadece poliçe kesmez, müşterinin gerçek\nriskini analiz eder.\n\nDanışman şunları sorgulamalıdır:\n\n> • İşletmenin faaliyet konusu nedir?\\\n> • İçeride yanıcı madde var mı?\\\n> • Elektrik tesisatı ne durumda?\\\n> • Yangın söndürme sistemi var mı?\\\n> • Stok miktarı dönemsel değişiyor mu?\n\nDoğru analiz yapılmazsa müşteri eksik veya yanlış güvence almış olur.\n\n**3. DOĞAL AFET SİGORTALARI**\n\nDoğal afetler, insanların kontrolü dışında meydana gelen ve kısa sürede\nçok büyük maddi kayıplara yol açabilen olaylardır. Bu tür afetler aynı\nanda çok sayıda bina, işyeri ve insanı etkileyebilir. Bu nedenle doğal\nafetler, sigorta sektörünün en önemli risk alanlarından biridir.\n\nTürkiye, coğrafi yapısı nedeniyle birçok doğal afet riskine açık bir\nülkedir. Özellikle deprem, sel ve fırtına olayları her yıl ciddi\nhasarlara neden olmaktadır.\n\n**Başlıca Doğal Afet Riskleri**\n\n**Deprem**\n\nYer kabuğundaki kırılmalar sonucu oluşan sarsıntılar binalarda ağır\nhasara veya yıkıma yol açabilir. Türkiye, dünyanın en aktif deprem\nkuşaklarından biri üzerinde yer alır.\n\n> Örnek:\\\n> 1999 Marmara Depremi ve 2023 Kahramanmaraş depremleri yüz binlerce\n> binada hasar oluşturmuştur.\n\n**Sel ve Su Baskını**\n\nYoğun yağış, dere taşması veya altyapı yetersizliği sonucu oluşan su\nbaskınları özellikle bodrum katları ve işyerlerini ciddi şekilde\netkiler.\n\n> Örnek:\\\n> Sanayi sitelerinde depolardaki malların tamamen kullanılamaz hale\n> gelmesi.\n\n**Fırtına**\n\nŞiddetli rüzgâr çatı uçmaları, cam kırılmaları ve yapı hasarlarına neden\nolabilir.\n\n> Örnek:\\\n> Fırtına sonucu işyeri çatısının uçması ve içerdeki malların zarar\n> görmesi.\n\n**Dolu**\n\nÖzellikle araçlar ve çatı kaplamaları doludan zarar görebilir.\n\n> Örnek:\\\n> Açık otoparktaki araçların kaportasında ciddi hasar oluşması.\n\n**Heyelan (Toprak Kayması)**\n\nEğimli bölgelerde toprak hareketleri sonucu binalar zarar görebilir.\n\n**Türkiye'de Zorunlu Deprem Sigortası (DASK)**\n\nTürkiye'de konutlar için **Zorunlu Deprem Sigortası**, yani DASK\nuygulaması bulunmaktadır.\n\nBu sistemin amacı:\n\n-   Deprem sonrası vatandaşların tamamen mağdur olmasını önlemek,\n\n-   Devlet üzerindeki ekonomik yükü azaltmak,\n\n-   konut sahiplerinin temel zararlarını karşılamaktır.\n\n**DASK Neleri Karşılar?**\n\nDASK sadece **binanın kendisinde oluşan zararları** karşılar.\n\n> Teminat kapsamı:\\\n> • Binanın ana yapısı\\\n> • Temeller\\\n> • Ana duvarlar\\\n> • Merdivenler\\\n> • Asansörler\\\n> • Ortak alanlar\n\n**DASK Neleri Karşılamaz?**\n\n> DASK:\\\n> • Ev eşyalarını,\\\n> • kira kaybını,\\\n> • geçici konaklama giderlerini,\\\n> • iş durması zararlarını karşılamaz.\n\nBu nedenle yalnızca DASK yaptırmak yeterli değildir.\n\n**Konut Sigortasının Önemi**\n\nDASK sadece binayı korurken, konut sigortası:\n\n> ✔ Ev eşyalarını\\\n> ✔ Elektronik cihazları\\\n> ✔ Su baskını zararlarını\\\n> ✔ Cam kırılmalarını\\\n> ✔ Kira kaybını\\\n> ✔ Üçüncü şahıs zararlarını\n\nda kapsayabilir.\n\n> Bu nedenle ideal güvence:\\\n> **DASK + Konut Sigortası birlikte yapılmasıdır.**\n\n**Doğal Afet Sigortalarında Danışmanın Önemi**\n\nBirçok kişi yalnızca zorunlu olduğu için DASK yaptırır. Ancak büyük\nafetlerde asıl maddi kayıp ev eşyalarında ve yaşam düzeninde oluşur.\n\nİyi bir sigorta danışmanı müşteriye şunları anlatmalıdır:\n\n> • DASK yeterli değildir.\\\n> • Eşyalar ayrı güvence altına alınmalıdır.\\\n> • Kira kaybı ve alternatif konaklama teminatı önemlidir.\n\n**4. KARA ARAÇLARI SİGORTALARI**\n\nKara araçları sigortaları, sigorta sektöründe en yaygın kullanılan\nbranşlardan biridir. Trafikte milyonlarca araç bulunması ve kazaların\nsık yaşanması nedeniyle bu branş günlük hayatta en fazla karşılaşılan\nsigorta türüdür. Araç kazaları yalnızca maddi hasara değil, yaralanma,\nsakatlanma ve yüksek tazminat risklerine de yol açabilir. Bu nedenle\naraç sigortaları hem araç sahiplerini hem de üçüncü kişileri koruyan\nönemli bir güvence sistemidir.\n\nKara araçları sigortaları iki ana başlık altında incelenir:\n\n> • Zorunlu Trafik Sigortası\\\n> • Kasko Sigortası\n\n**1) Trafik Sigortası (Zorunlu Mali Sorumluluk Sigortası)**\n\nTrafik sigortası, kanunen yaptırılması zorunlu bir sigortadır. Trafiğe\nçıkan her motorlu aracın bu sigortaya sahip olması gerekir.\n\nBu sigorta **araç sahibini değil, kazada zarar gören karşı tarafı\nkorur.**\n\n**Trafik Sigortası Neyi Karşılar?**\n\nBir kazada kusurlu taraf sizseniz, karşı tarafın zararları poliçe\nkapsamında karşılanır.\n\n> Teminatlar:\\\n> • Karşı aracın hasarı\\\n> • Karşı taraftaki kişilerin tedavi giderleri\\\n> • Sakatlanma ve vefat tazminatları\\\n> • Üçüncü şahıs mallarına verilen zararlar\n\n**Trafik Sigortası Neyi Karşılamaz?**\n\n> • Kendi aracınızın hasarı\\\n> • Kendi yaralanmanız\\\n> • Kendi aracınızdaki zararlar\n>\n> Örnek:\\\n> Siz hatalı bir şekilde başka araca çarparsanız:\n\n-   Karşı aracın hasarını trafik sigortanız öder.\n\n-   Ancak sizin aracınızı ödemez.\n\nBu nedenle trafik sigortası tek başına yeterli değildir.\n\n**2) Kasko Sigortası**\n\nKasko sigortası, araç sahibinin kendi aracını güvence altına alan isteğe\nbağlı bir sigortadır.\n\nKasko, aracın karşılaşabileceği birçok riski teminat altına alır.\n\n**Kasko Teminatları**\n\nStandart kasko poliçelerinde temel teminatlar şunlardır:\n\n> • Çarpma ve çarpışma\\\n> • Aracın sabit bir cisme çarpması\\\n> • Aracın devrilmesi veya düşmesi\\\n> • Yanma\\\n> • Hırsızlık\\\n> • Hırsızlığa teşebbüs zararları\n\n**Doğal Afet Teminatları**\n\nBirçok kasko poliçesi şu zararları da kapsar:\n\n> • Sel ve su baskını\\\n> • Dolu zararları\\\n> • Fırtına zararları\\\n> • Deprem kaynaklı hasarlar\n>\n> Örnek:\\\n> Açık otoparktaki aracın dolu yağışı sonucu hasar görmesi.\n\n**Ek Hizmet ve Teminatlar**\n\nKasko poliçeleri sadece hasar ödemesi değil, birçok ek hizmet de sunar.\n\n**Yol Yardım Hizmeti**\n\nAraç yolda kaldığında çekici, lastik değişimi veya yakıt desteği\nsağlanabilir.\n\n**İkame Araç**\n\nAraç servisteyken geçici araç temin edilir.\n\n**Mini Onarım Hizmeti**\n\nKüçük çizik, göçük ve cam hasarları hasarsızlık indirimi bozulmadan\ngiderilebilir.\n\n**Kasko Poliçelerinde Sık Yapılan Hatalar**\n\nEn sık karşılaşılan yanlışlar:\n\n> • En ucuz poliçeyi seçmek\\\n> • Yanlış araç değeri belirlemek\\\n> • Eksik teminat almak\\\n> • Muafiyet şartlarını okumamak\n\nUcuz poliçe her zaman iyi poliçe değildir.\n\n**Danışmanın Rolü**\n\nSigorta danışmanının görevi sadece poliçe kesmek değil, müşterinin\nkullanım alışkanlıklarına uygun poliçe oluşturmaktır.\n\nÖrneğin danışman şunları sormalıdır:\n\n> • Araç nerede kullanılıyor?\\\n> • Açık mı kapalı otopark mı?\\\n> • Araç ticari mi özel mi?\\\n> • Sürücü profili nasıl?\n\nDoğru analiz doğru güvence sağlar.\n\n**5. GENEL ZARARLAR SİGORTALARI (ALL RISK)**\n\nBirçok farklı riski kapsayan geniş bir branştır.\n\nÖrnek teminatlar:\n\n-   Hırsızlık sigortası\n\n-   Cam kırılması\n\n-   Elektronik cihaz sigortası\n\n-   Makine kırılması\n\n-   İnşaat all-risk sigortaları\n\nÖzellikle işletmeler için önemlidir.\n\n**6. TARIM SİGORTALARI**\n\nTarım faaliyetleri doğa şartlarından çok etkilenir. Türkiye'de bu sistem\n**TARSİM** tarafından yürütülür.\n\nTeminat kapsamı:\n\n-   Don\n\n-   Dolu\n\n-   Fırtına\n\n-   Sel\n\n-   Kuraklık\n\n-   Hayvan hayat sigortaları\n\nDevlet prim desteği sağlar.\n\n**7. GENEL SORUMLULUK SİGORTALARI**\n\nİşletmeler üçüncü kişilere zarar verebilir. Bu zararların tazmini\nişletme tarafından ödenir.\n\nSorumluluk sigortaları:\n\n-   ziyaretçi kazaları\n\n-   müşteri yaralanmaları\n\n-   ürün kaynaklı zararlar\\\n    gibi durumlarda işletmeyi korur.\n\n**8. MESLEKİ SORUMLULUK SİGORTALARI**\n\nBazı mesleklerde yapılan hatalar büyük zararlara yol açabilir.\n\nÖrnek:\n\n-   Doktorlar\n\n-   Avukatlar\n\n-   Mali müşavirler\n\n-   Mühendisler\n\n-   Danışmanlar\n\nBu poliçeler mesleki hatalardan doğan zararları teminat altına alır.\n\n**9. FİNANSAL KAYIPLAR SİGORTALARI**\n\nMaddi zarar dışında gelir kayıplarını da kapsar.\n\nÖrnek:\n\n-   İş durması sigortaları\n\n-   Alacak sigortaları\n\n-   Kredi teminat sigortaları\n\n-   Kefalet sigortaları\n\n**10. DİJİTALLEŞME VE SİBER RİSKLER**\n\n> Günümüzde şirketlerin en büyük risklerinden biri dijital\n> saldırılardır.\n\nRiskler:\n\n-   Veri kaybı\n\n-   Sistem çökmesi\n\n-   Fidye yazılım saldırıları\n\n-   Veri ihlalleri\n\n**11. SİBER RİSK SİGORTALARI**\n\nBu poliçeler:\n\n-   Veri kaybı zararlarını,\n\n-   sistem durması kayıplarını,\n\n-   hukuki sorumlulukları,\n\n-   itibar kaybı giderlerini\n\nteminat altına alır.\n\n> Yeni ve hızla büyüyen bir branştır.\n\n**12. SAĞLIK SİGORTALARI**\n\nSağlık sigortaları, kişilerin hastalık veya kaza sonucu ihtiyaç duyduğu\nsağlık hizmetlerine daha hızlı ve kaliteli şekilde ulaşmasını sağlayan\nsigorta türleridir.\n\nGünümüzde sağlık harcamaları ciddi maliyetlere ulaşabilmektedir.\nÖzellikle özel hastanelerde yapılan ameliyatlar, tedaviler ve uzun\nsüreli yatışlar yüksek faturalar oluşturabilir.\n\nSağlık sigortası, bu beklenmedik sağlık giderlerinin finansal yükünü\nazaltarak kişinin bütçesini korur.\n\nTürkiye'de sağlık sigortaları genel olarak iki ana başlık altında\nincelenir:\n\n> • Özel Sağlık Sigortası (ÖSS)\\\n> • Tamamlayıcı Sağlık Sigortası (TSS)\n\n**1) Özel Sağlık Sigortası (ÖSS)**\n\nÖzel sağlık sigortası, sigortalının özel hastanelerden kapsamlı sağlık\nhizmeti almasını sağlar.\n\nBu poliçelerde kişi, SGK'ya bağlı olmadan özel sağlık kuruluşlarında\ntedavi olabilir.\n\n**Özel Sağlık Sigortasının Karşıladığı Başlıca Giderler**\n\nPoliçeye göre değişmekle birlikte genellikle:\n\n> • Muayene giderleri\\\n> • Tahlil ve tetkikler\\\n> • Ameliyat giderleri\\\n> • Hastane yatış masrafları\\\n> • Yoğun bakım giderleri\\\n> • İlaç ve tedavi giderleri\n\nteminat altına alınabilir.\n\n**Kimler Tercih Eder?**\n\n> • Daha geniş hastane ağı isteyenler\\\n> • SGK'ya bağlı çalışmayan kişiler\\\n> • Daha kapsamlı sağlık güvencesi isteyen aileler\n\n**Avantajı**\n\nKişi istediği özel hastaneye daha geniş kapsamda erişebilir.\n\n**Dezavantajı**\n\nTamamlayıcı sağlık sigortasına göre primi daha yüksektir.\n\n**2) Tamamlayıcı Sağlık Sigortası (TSS)**\n\nTamamlayıcı sağlık sigortası, SGK'lı çalışanlar için geliştirilmiş bir\nsistemdir. SGK anlaşmalı özel hastanelerde oluşan **fark ücretini**\nkarşılar.\n\n**Nasıl Çalışır?**\n\nNormalde SGK anlaşmalı özel hastaneler, SGK'nın ödediği tutarın üzerinde\nhastadan fark ücreti alır. Tamamlayıcı sağlık sigortası bu fark ücretini\nkarşılar ve kişi ek ücret ödemeden tedavi olabilir.\n\n**Kimler Yararlanabilir?**\n\n> • SGK'lı çalışanlar\\\n> • Emekliler\\\n> • SGK kapsamındaki aile bireyleri\n\n**Avantajı**\n\n> • Daha uygun primlidir.\\\n> • Özel hastanede düşük maliyetle hizmet alınır.\n\n**Sınırlamaları**\n\n> • SGK anlaşması olmayan hastanelerde geçerli değildir.\\\n> • Teminat kapsamı ÖSS'ye göre daha sınırlı olabilir.\n\n**Sağlık Sigortalarında Bekleme Süreleri**\n\nBirçok sağlık poliçesinde bazı hastalıklar için bekleme süresi\nuygulanır.\n\nÖrnek:\n\n-   Ameliyat gerektiren bazı hastalıklar ilk yıl kapsam dışında\n    kalabilir.\n\n-   Doğum teminatında genellikle bekleme süresi vardır.\n\nBu nedenle sigorta **hastalık ortaya çıktıktan sonra değil, sağlıklıyken\nyapılmalıdır.**\n\n**En Sık Yapılan Yanlış Anlama**\n\nBirçok kişi sağlık sigortasını yalnızca hastalandığında yaptırmak ister.\nAncak gerçekleşmiş veya başlamış hastalıklar çoğu zaman poliçe kapsamına\nalınmaz.\n\nSigorta, ortaya çıkmış bir sorunun çözümü değil, gelecekte oluşabilecek\nrisklere karşı güvencedir.\n\n**Danışmanın Rolü**\n\nSigorta danışmanı müşteriye şunları net şekilde anlatmalıdır:\n\n> • Hangi hastaneler poliçe kapsamında?\\\n> • Ayakta tedavi limiti nedir?\\\n> • Yatarak tedavi neleri kapsar?\\\n> • Bekleme süreleri var mı?\n\nDoğru bilgilendirme müşteri memnuniyetini artırır.\n\n=== BÖLÜM: HAYAT SİGORTALARI (Kavram, Mevzuat, Sözleşme, Lehtar, Ürün Türleri, Risk Analizi, Prim İadeli Hayat Sigortası) ===\n\n**HAYAT SİGORTALARI**\n\nHayat sigortaları, kişinin yaşamı boyunca karşılaşabileceği ölüm,\nsakatlık veya gelir kaybı gibi risklerin finansal sonuçlarını güvence\naltına alan sigorta ürünleridir. Bu sigortalar sadece vefat teminatı\nsunmakla kalmaz, aynı zamanda uzun vadeli **tasarruf**, **mali\ngüvence**, ve **aile planlaması** amacıyla da kullanılabilir.\n\n**Hayat Sigortalarının Temel Amaçları**\n\n> • Ailenin gelir kaybını önlemek\\\n> • Borçların geride kalanlara yük olmamasını sağlamak\\\n> • Uzun vadeli finansal güvence oluşturmak\\\n> • Tasarruf ve birikim disiplinini desteklemek\n\n**1. Hayat Sigortaları: Kavramsal Çerçevesi ve Tarihsel Gelişimi**\n\nHayat sigortası, ticaretin ve ücretli çalışma sisteminin geliştiği\ndönemlerde aile reisinin vefatı sonrası geride kalanların ekonomik\nolarak korunması ihtiyacından doğmuştur.\\\n17. yüzyıldan itibaren Avrupa'da ortaya çıkan bu uygulamalar modern\nhayat sigortacılığının temelini oluşturmuştur.\n\n> Hayat sigortalarının gelişimini hızlandıran etkenler:\\\n> • Ticaretin büyümesi\\\n> • Şehirleşmenin artması\\\n> • Ücretli çalışma sisteminin yaygınlaşması\\\n> • Aile gelirinin tek bir kişiye bağlı hale gelmesi\n\nBu unsurlar, 20. yüzyılda hayat sigortalarını aile finans planlamasının\ntemel unsurlarından biri haline getirmiştir.\n\n**2. Hayat Sigortası Mevzuatının Kaynakları**\n\nTürkiye'de hayat sigortaları, belirli yasal düzenlemelere göre\nyürütülür. Bu düzenlemeler, sigortalı ve sigorta şirketleri arasındaki\nilişkileri, tarafların hak ve yükümlülüklerini belirler.\n\n> Başlıca kaynaklar:\\\n> • Türk Ticaret Kanunu\\\n> • Sigortacılık Kanunu\\\n> • SEDDK düzenlemeleri\\\n> • Sigorta Genel Şartları\\\n> • Hayat sigortalarına ilişkin yönetmelikler\n\nBu mevzuat, müşterilerin korunmasını ve sigortacılık faaliyetlerinin\ngüvenli bir şekilde yürütülmesini sağlar.\n\n**3. Hayat Sigortası Sözleşmesi**\n\nHayat sigortası sözleşmesi, sigorta şirketi ile sigortalı arasında\nyapılan ve belirli risklerin gerçekleşmesi hâlinde ödeme yapılmasını\nöngören yazılı bir sözleşmedir.\n\n> Sözleşmede yer alan temel unsurlar:\\\n> • **Sigortalı kişi**\\\n> • **Lehtar** (tazminatı alacak kişi)\\\n> • **Sigorta süresi**\\\n> • **Teminat tutarı**\\\n> • **Ödenecek prim**\\\n> • **Teminat kapsamı**\n\n**Lehtar (Beneficiary) Nedir?**\n\nLehtar, hayat sigortasında ödeme yapılacak kişidir.\\\nÖrneğin; sigortalı vefat ettiğinde ödeme **eşine**, **çocuklarına** veya\npoliçede belirlenen başka bir kişiye yapılabilir.\n\nLehtar belirlenmesi, sigortanın amacına ulaşması için kritik bir\nunsurdur.\n\n**4. Türkiye'de Hayat Sigortalarının Gelişimi**\n\n> Türkiye'de hayat sigortaları ilk olarak **kredi bağlantılı** ürünlerle\n> yaygınlaşmıştır:\\\n> • Konut kredileri\\\n> • İhtiyaç kredileri\\\n> • Ticari krediler\n\nBankalar kredi sürecinde hayat sigortası yaptırarak riski güvence altına\nalmışlardır.\n\n> Son yıllarda ise hayat sigortaları:\\\n> • Bireysel finansal planlama\\\n> • Uzun vadeli tasarruf ürünleri\\\n> • Çocuklar için birikim planları\n\ngibi ihtiyaçlarla **bireysel müşterilere** daha yaygın şekilde\nsunulmaktadır.\n\n**5. Hayat Sigortası Ürünleri**\n\nHayat sigortaları, ürün özelliklerine göre iki ana gruba ayrılır:\n\n**A) Risk Ağırlıklı Hayat Sigortaları**\n\nBu ürünlerde amaç sadece riske karşı güvence sağlamaktır.\\\nVefat veya belirlenmiş risklerin gerçekleşmesi durumunda lehtara ödeme\nyapılır.\n\n> Örnekler:\\\n> • Vefat teminatlı hayat sigortaları\\\n> • Kredi hayat sigortaları\n\n**B) Birikimli Hayat Sigortaları**\n\nBu ürünler hem güvence sağlar hem de belirli süre sonunda\n**tasarruf/birikim** oluşturur.\\\nSözleşme süresi sona erdiğinde sigortalıya ödeme yapılır.\n\n> Örnekler:\\\n> • Çocuk eğitim birikim planları\\\n> • Uzun vadeli tasarruf poliçeleri\n\n**6. Hayat Sigortalarında Risk Analizi**\n\nHayat sigortalarında risk değerlendirmesi, sigortalının **insan\nhayatı**yla doğrudan ilgili olduğundan farklıdır. Bu nedenle sigorta\nşirketleri prim belirlerken birçok faktörü detaylı değerlendirmek\nzorundadır.\n\n> Değerlendirilen başlıca kriterler:\\\n> • **Yaş** -- Genç yaşta risk daha azdır\\\n> • **Cinsiyet** -- Kadın ve erkeğin yaşam beklentileri farklıdır\\\n> • **Meslek** -- Tehlikeli mesleklerde risk yüksektir\\\n> • **Sağlık durumu** -- Kronik hastalıklar primi artırır\\\n> • **Sigara kullanımı** -- Sigara kullananlarda risk yüksektir\\\n> • **Geçmiş hastalıklar** -- Önceki sağlık geçmişi önemli etkendir\\\n> • **Hobi ve yaşam tarzı** -- Maceracı hobiler risk artışına neden olur\n>\n> **Örnek risk farkları:**\\\n> • Masa başı çalışan ile maden işçisinin risk profilleri farklıdır.\\\n> • Sigara kullanan kişinin sağlık riski daha yüksektir.\\\n> • Ağır spor yapan kişiler daha yüksek risk grubunda olabilir.\n\nRisk arttıkça prim tutarı da yükselir.\n\n**Prim İadeli Hayat Sigortası (Garanti BBVA Emeklilik)**\n\nBu ürün, standart hayat sigortası prensibini **ek bir avantajla**\nbirleştirir:\n\n**Temel Özellikler**\n\n> • Poliçe süresi **12 yıldır**.\\\n> • Vefat riskine karşı belirlenen teminatla **yakınlar güvende** olur.\\\n> • **Risk gerçekleşmezse**, yani sigortalı süre sonunda hayatta kalırsa\n> poliçe sürecinde ödenen **tüm primler geri iade edilir**.\n\nBu ürün, klasik \"return of premium\" (prim iadeli) hayat sigortası\nmantığıyla çalışır; bazı uluslararası versiyonlarda da benzer şekilde\nprim geri iadesi özelliği bulunur.\n\n**Avantajlar**\n\n> • Sigortadan faydalanılmazsa ödediğiniz primler size geri döner.\\\n> • Sigortaya paralel olarak **%27'ye varan vergi avantajı**\n> uygulanabilir.\\\n> • Aylık, 3 aylık, 6 aylık veya yıllık ödeme seçenekleri vardır.\n\n**Dikkat Edilmesi Gerekenler**\n\n> • İlk yıl poliçeden ayrılmada kesintiler olabilir.\\\n> • Ürün döviz endeksli olarak çalışabilir; bu nedenle kur farkı etkisi\n> olabilir.\n\nBu ürün, **risk güvencesi + tasarruf garantisi** sunar.\\\nSigorta süresince risk gerçekleşirse lehtar tazminat alır,\ngerçekleşmezse primler geri döner.\n\nBu nedenle sigortalıya \"**hayatta kalırsan ödediğin primleri geri\nalırsın**\" gibi bir anlatım yapılabilir.\n\n**Prim İadeli Hayat Sigortasının En Önemli 5 Faydası**\n\nBu ürün, hem hayat güvencesi hem de birikim avantajını birlikte sunması\nnedeniyle müşteriler açısından önemli avantajlar sağlar. Öne çıkan\nbaşlıca faydalar şunlardır:\n\n**1. Vefat Teminatı ile Oluşabilecek Masraflara Karşı Güvence**\n\nSigortalının vefatı halinde ailesinin karşılaşabileceği:\n\n-   Cenaze giderleri\n\n-   Kredi ve borç ödemeleri\n\n-   Günlük yaşam giderleri\n\n-   Çocukların eğitim masrafları\n\ngibi finansal yükler sigorta teminatı sayesinde karşılanabilir ve aile\nekonomik olarak korunmuş olur.\n\n**2. Vergi Avantajı Sağlar**\n\nÖdenen primler, yürürlükteki mevzuat kapsamında belirli limitler\ndahilinde gelir vergisi matrahından indirilebilir.\\\nBu da sigortalıya **fiilen daha düşük maliyetle güvence ve birikim\nimkânı** sunar.\n\n**3. Banka Kredilerine Bağlı Hayat Sigortalarından Muafiyer Sağlar**\n\nBankaların kredi sırasında yaptığı hayat sigortaları genellikle:\n\n-   Kredi süresiyle sınırlıdır\n\n-   Kredi borcunu güvence altına alır\n\n-   Müşteri lehine kalıcı birikim oluşturmaz\n\nPrim iadeli hayat sigortası ise **kişiye özel, krediye bağlı olmayan ve\nuzun vadeli güvence sunan** bağımsız bir poliçedir.\n\n**4. Poliçedeki Birikim Haczedilemez**\n\nHayat sigortalarında belirli şartlar altında poliçedeki hak ve alacaklar\n**hacze konu edilemez**.\\\nBu özellik, özellikle ticari faaliyet yürüten kişiler için önemli bir\ngüvence oluşturur.\n\n**5. Kesintisiz Döviz Bazlı Birikim İmkânı**\n\nÜrün, döviz bazlı birikim yapma imkânı sunduğundan:\n\n-   Uzun vadede kur artışlarından korunma sağlar\n\n-   Birikimin reel değerini korumaya yardımcı olur\n\n-   Tasarruf disiplini oluşturur\n\nve müşteriye alternatif bir döviz birikim aracı sunar.\n\n=== BÖLÜM: BİREYSEL EMEKLİLİK SİSTEMİ - BES (Amaç, İşleyiş, Devlet Katkısı, Emekliliğe Hak Kazanma, Fonlar, BES vs Hayat Sigortası Farkları) ===\n\n**BİREYSEL EMEKLİLİK SİSTEMİ (BES)**\n\nBireysel Emeklilik Sistemi (BES), kişilerin aktif çalışma hayatları\nboyunca düzenli birikim yaparak emeklilik dönemlerinde ek gelir elde\netmelerini sağlayan uzun vadeli tasarruf ve yatırım sistemidir. BES,\nsosyal güvenlik sisteminin yerine geçmez; emeklilik döneminde ikinci bir\ngelir kaynağı oluşturmayı hedefler. Sistem devlet tarafından\ndesteklenmekte ve katılımcıların düzenli tasarruf yapması teşvik\nedilmektedir.\n\n**1. Bireysel Emeklilik Sisteminin Amacı**\n\nBES'in temel amaçları şunlardır:\n\n> • Çalışma döneminde düzenli tasarruf oluşturmak\\\n> • Emeklilik döneminde ek gelir sağlamak\\\n> • Uzun vadeli yatırım alışkanlığı kazandırmak\\\n> • Ekonomiye uzun vadeli fon kaynağı sağlamak\\\n> • Kişilerin finansal geleceğini güvence altına almak\n\nKısacası BES, bugünden küçük birikimlerle gelecekte mali rahatlık\nsağlamayı amaçlar.\n\n**2. Sistem Nasıl Çalışır?**\n\nBES'e katılan kişi:\n\n> • Bir emeklilik şirketi ile sözleşme yapar.\\\n> • Her ay belirlediği katkı payını yatırır.\\\n> • Yatırılan tutar yatırım fonlarında değerlendirilir.\\\n> • Devlet katkısı sisteme eklenir.\\\n> • Birikim zaman içinde büyür.\n\nFon getirileri ve devlet katkısı sayesinde birikim uzun vadede artar.\n\n**3. Devlet Katkısı Avantajı (Güncel)**\n\nBES'in en önemli avantajı devlet katkısıdır.\n\nKatılımcının ödediği katkı payının:\n\n**%20'si kadar devlet katkısı eklenir.**\n\n**Örnek:**\n\n> Aylık 3.000 TL yatıran bir kişi için\\\n> Devlet her ay **600 TL** ek katkı sağlar.\n\nDevlet katkısı belirli süreler sonunda hak edilir:\n\n> • 3 yıl sonunda %15\\\n> • 6 yıl sonunda %35\\\n> • 10 yıl sonunda %60\\\n> • Emeklilikte %100\n\nBu nedenle BES uzun vadeli kalındığında en avantajlı hale gelir.\n\n**4. Emekliliğe Hak Kazanma Şartları**\n\nBES'te emeklilik hakkı kazanmak için:\n\nSistemde en az 10 yıl kalmak ve 56 yaşını doldurmak gerekir.\n\nBu şartlar sağlandığında katılımcı:\n\n> • Birikimini toplu para olarak alabilir,\\\n> • Maaş şeklinde alabilir,\\\n> • Ya da karma ödeme seçebilir.\n\n**5. BES Fonları Nasıl Çalışır?**\n\nKatkı payları farklı yatırım fonlarında değerlendirilir.\n\nBaşlıca fon türleri:\n\n> • Hisse senedi fonları\\\n> • Borçlanma araçları fonları\\\n> • Altın fonları\\\n> • Döviz fonları\\\n> • Katılım fonları\\\n> • Karma fonlar\n\nKatılımcı risk tercihine göre fon seçebilir ve yıl içinde fon dağılımını\ndeğiştirebilir.\n\n**6. BES'in Sağladığı Avantajlar**\n\nBES katılımcısına birçok avantaj sunar:\n\n> • %20 devlet katkısı avantajı\\\n> • Uzun vadeli birikim imkânı\\\n> • Profesyonel fon yönetimi\\\n> • Fon dağılımını değiştirme esnekliği\\\n> • Ek emeklilik geliri oluşturma\\\n> • Düzenli tasarruf alışkanlığı kazanma\n\n**7. BES'ten Ayrılma ve Ara Verme**\n\nKatılımcılar:\n\n> • İstedikleri zaman sistemden çıkabilir,\\\n> • Ödemelerine ara verebilir,\\\n> • Katkı payını artırıp azaltabilir.\n\nAncak erken çıkışta:\n\n> • Devlet katkısının tamamı alınamaz,\\\n> • Uzun vadeli getiriden vazgeçilmiş olur.\n\nBu nedenle BES uzun vadeli planlama aracıdır.\n\n**8. BES ile Hayat Sigortası Arasındaki Farklar**\n\nBES ve hayat sigortası sıkça karıştırılır; ancak amaçları farklıdır.\n\n  -----------------------------------------------------------------------\n  **Konu**            **Hayat Sigortası**         **BES**\n  ------------------- --------------------------- -----------------------\n  Ana Amaç            Risk koruması               Emeklilik birikimi\n\n  Odak                Güvence                     Yatırım ve birikim\n\n  Devlet Katkısı      Yok                         %20\n\n  Ödeme Zamanı        Risk gerçekleştiğinde       Emeklilikte\n\n  Süre                Poliçe süresine bağlı       10 yıl + 56 yaş\n  -----------------------------------------------------------------------\n\nÖzetle:\n\n• Hayat sigortası → Bugünün risklerine karşı koruma sağlar.\\\n• BES → Gelecekte gelir oluşturur.\n\n**9. BES Danışmanının Rolü**\n\nBES satışında danışmanın görevi:\n\n> • Müşterinin gelir durumunu analiz etmek\\\n> • Uygun katkı payını belirlemek\\\n> • Risk profiline uygun fon seçmek\\\n> • Fon performansını düzenli kontrol etmek\\\n> • Uzun vadeli finansal planlama sunmaktır.\n\nİyi danışman BES'i bir ürün değil, **gelecek planı** olarak anlatır.\n\n=== BÖLÜM: VERGİ SİSTEMİ VE SİGORTACILIKLA İLİŞKİSİ (Gelir Vergisi, Stopaj, Brüt/Net Maaş, Vergi İadesi Mantığı, Hayat Sigortası/BES/Sağlık Sigortası Vergi Avantajları, Veraset ve İntikal Vergisi) ===\n\n**VERGİ SİSTEMİ**\n\n**1. Vergi Nedir ve Neden Alınır?**\n\nVergi, devletin kamu hizmetlerini finanse etmek amacıyla vatandaşlardan\nve işletmelerden kanunla aldığı zorunlu ödemedir.\n\nDevlet;\n\n-   güvenlik,\n\n-   eğitim,\n\n-   sağlık,\n\n-   ulaşım,\n\n-   altyapı,\n\n-   adalet\n\ngibi hizmetleri yürütmek için gelire ihtiyaç duyar. Vergiler bu\ngelirlerin temel kaynağıdır.\n\nTarihsel olarak ilk vergiler ürün ve toprak üzerinden alınırken, modern\ndönemde gelir ve tüketim üzerinden alınan para vergileri\nyaygınlaşmıştır.\n\nBugün vergi sistemi sadece gelir toplamak için değil, aynı zamanda:\n\n-   ekonomik düzeni sağlamak,\n\n-   gelir dağılımını dengelemek,\n\n-   bazı harcamaları teşvik etmek\n\namacıyla da kullanılır.\n\n**2. Vergiler Nasıl Sınıflandırılır?**\n\nVergiler temel olarak iki gruba ayrılır:\n\n**Dolaysız Vergiler**\n\nKişinin gelir veya kazancı üzerinden alınır.\n\nÖrnek:\n\n-   Gelir Vergisi\n\n-   Kurumlar Vergisi\n\n-   Motorlu Taşıtlar Vergisi\n\n**Dolaylı Vergiler**\n\nMal ve hizmet tüketimi sırasında ödenir.\n\nÖrnek:\n\n-   KDV\n\n-   ÖTV\n\n-   akaryakıt vergileri\n\nVatandaş çoğu zaman farkında olmadan bu vergileri öder.\n\n**3. Gelir Vergisi Nedir?**\n\nGelir vergisi, kişilerin bir yıl içinde elde ettiği kazanç üzerinden\nalınan vergidir.\n\nGelir türleri:\n\n-   Ücret gelirleri\n\n-   Ticari kazançlar\n\n-   Serbest meslek kazançları\n\n-   Kira gelirleri\n\n-   Menkul sermaye gelirleri\n\n-   Değer artış kazançları\n\nGelir vergisi artan oranlıdır. Gelir yükseldikçe uygulanan vergi oranı\nartar.\n\n**4. Vergi Dilimi Nedir?**\n\nGelir arttıkça kişi daha yüksek oranlı vergi dilimine girer.\n\nBu nedenle çalışanlar yılın son aylarında:\n\n-   daha fazla vergi öder,\n\n-   net maaş düşmüş gibi hissedilir.\n\nDanışman, müşterinin maaşındaki değişimi doğru açıklayabilmelidir.\n\n> **5. Stopaj Nedir?**\n\nStopaj, verginin gelir sahibine ulaşmadan önce kesilmesidir.\n\n> Örnek:\\\n> Çalışanın vergisi işveren tarafından kesilip devlete ödenir.\n\nÇalışan maaşını vergisi düşülmüş şekilde alır.\n\nStopaj uygulanan gelirler:\n\n-   ücret gelirleri,\n\n-   kira ödemeleri,\n\n-   serbest meslek ödemeleri,\n\n-   faiz gelirleri.\n\n**6. Brüt Maaş -- Net Maaş Farkı**\n\n**Brüt maaş**\n\nİşverenin çalışan için belirlediği toplam ücret tutarıdır.\n\n**Net maaş**\n\nKesintilerden sonra çalışanın eline geçen tutardır.\n\nKesintiler:\n\n-   SGK işçi payı\n\n-   İşsizlik primi\n\n-   Gelir vergisi\n\n-   Damga vergisi\n\n**SATIŞ AÇISINDAN ÖNEMİ**\n\nVergi avantajlı ürünlerde matrah düşürüldüğünde çalışan daha az vergi\nöder ve dolaylı olarak net geliri artar.\n\n**7. İşveren Maliyeti Nedir?**\n\nÇalışan sadece net maaşı görür; ancak işveren maliyeti daha yüksektir.\n\nİşveren ayrıca öder:\n\n-   SGK işveren payı\n\n-   işsizlik primi\n\n-   yan haklar\n\nBu nedenle bazı işverenler maaş yerine:\n\n-   özel sağlık sigortası,\n\n-   BES katkısı,\n\n-   hayat sigortası\n\ngibi yan haklar sunar.\n\n> Bu durum danışman için satış fırsatıdır.\n\n**8. Vergi İadesi Mantığı**\n\nDevlet bazı harcamaları teşvik etmek ister.\n\nBu nedenle kişi:\n\n-   sağlık harcaması,\n\n-   eğitim harcaması,\n\n-   sigorta primi\n\nödediğinde vergi matrahı düşer ve daha az vergi öder.\n\nYani kişinin zaten ödeyeceği verginin bir kısmı kendisi için harcanmış\nolur.\n\n**9. Ücretli ve Serbest Çalışan Vergi Farkı**\n\n**Ücretli çalışan**\n\n-   Vergi işveren tarafından kesilir.\n\n-   Beyanname vermez.\n\n**Serbest çalışan / şirket sahibi**\n\n-   Gelirini beyan eder.\n\n-   Vergisini kendisi öder.\n\n-   Giderlerini düşebilir.\n\n\\*Danışman müşterinin hangi grupta olduğunu bilmelidir.\n\n**Gelir Vergisi Tarifesi**\n\n**2026 takvim yılı (G.V.K. madde:103) Gelir Vergisi Tarifesi**\n\n+----------------------------------------------------------------+-----+\n| 190.000 TL'ye kadar                                            | 15% |\n+================================================================+=====+\n| 400.000 TL'nin 190.000 TL'si için 28.500 TL, fazlası           | 20% |\n+----------------------------------------------------------------+-----+\n| 1.000.000 TL\\'nin 400.000 TL'si için 70.500 TL, (**ücret       | 27% |\n| gelirlerinde**                                                 |     |\n|                                                                |     |\n| **1.500.000 TL\\'nin 400.000 TL'si için 70.500 TL),** fazlası   |     |\n+----------------------------------------------------------------+-----+\n| 5.300.000 TL\\'nin 1.000.000 TL'si için 232.500 TL, (**ücret    | 35% |\n| gelirlerinde**                                                 |     |\n|                                                                |     |\n| **5.300.000 TL\\'nin 1.500.000 TL'si için 367.500 TL**),        |     |\n| fazlası                                                        |     |\n+----------------------------------------------------------------+-----+\n| 5.300.000 TL\\'den fazlasının 5.300.000 TL'si için 1.737.500    | 40% |\n| TL, (**ücret gelirlerinde 5.300.000 TL'den fazlasının          |     |\n| 5.300.000 TL'si için 1.697.500 TL), fazlası**                  |     |\n+----------------------------------------------------------------+-----+\n\n**10. Hayat Sigortalarında Vergi Avantajı**\n\nHayat sigortası primleri belirli oranlarda gelir vergisi matrahından\ndüşülebilir.\n\nBu da:\n\n-   daha az vergi ödenmesi,\n\n-   net gelirin korunması\n\nanlamına gelir.\n\nHayat sigortası:\n\n-   aile güvenliği,\n\n-   borçların korunması,\n\n-   gelir kaybının telafisi\n\namacını taşır.\n\n> **11. İvazlı ve İvazsız İntikal Nedir?**\n\nİntikal, mal veya paranın el değiştirmesidir.\n\n**İvazlı intikal**\n\nKarşılıklı işlem vardır. (satış gibi)\n\n**İvazsız intikal**\n\nKarşılıksız geçiştir. (miras, bağış gibi)\n\nBu durumda Veraset ve İntikal Vergisi doğar.\n\nBir kişinin vefatı halinde sahip olduğu malvarlığı mirasçılarına geçer.\nBu geçiş karşılıksız olduğu için **ivazsız intikal** sayılır ve\n**Veraset ve İntikal Vergisi** doğar.\n\nAncak birçok kişi şu gerçeği fark etmez:\n\nMiras kalan mal varlığı doğrudan kullanılamaz; önce vergi yükümlülükleri\nyerine getirilmelidir.\n\n**Veraset yoluyla intikal** ile **ivazsız (karşılıksız) intikal**\narasındaki fark, malın **nasıl ve hangi sebeple** el değiştirdiğiyle\nilgilidir.\n\n**1) Veraset yoluyla intikal (Miras)**\n\nBir kişinin **vefat etmesi sonucu** malvarlığının yasal mirasçılarına\ngeçmesidir.\n\nÖrnek:\n\n-   Babanın vefatı sonrası ev, para, arsa ve diğer varlıkların kanuni\n    mirasçılarına (çocuklara veya eşe) geçmesi.\n\n> Bu durumda uygulanan vergi:\\\n> **Veraset ve İntikal Vergisi -- veraset yoluyla intikal tarifesi**\\\n> (Bu tarife daha düşük oranlıdır.)\n\n**2) İvazsız (karşılıksız) intikal**\n\nMalın **ölüm olmadan**, karşılık alınmadan başka birine geçirilmesidir.\n\nÖrnek:\n\n-   Hayattayken çocuğa ev bağışlamak\n\n-   Birine karşılıksız para vermek\n\n-   Araba hediye etmek\n\n-   Çekiliş, piyango, yarışma kazanımı\n\n  ------------------------------------------------------------------------\n  **2026 Takvim Yılı Matrahı**     **Verginin Oranı (%)** \n  -------------------------------- ---------------------- ----------------\n                                   **Veraset Yoluyla      **İvazsız\n                                   İntikallerde**         İntikallerde**\n\n  İlk 3.000.000 TL için            1                      10\n\n  Sonra gelen 7.000.000 TL için    3                      15\n\n  Sonra gelen 15.000.000 TL için   5                      20\n\n  Sonra gelen 30.000.000 TL için   7                      25\n\n  Matrahın 55.000.000 TL'yi aşan   10                     30\n  bölümü için                                             \n  ------------------------------------------------------------------------\n\n**Mirasın Kullanılabilmesi İçin Verginin Ödenmesi Gerekir**\n\nVefat sonrası:\n\n-   banka hesaplarına,\n\n-   taşınmazlara,\n\n-   şirket hisselerine,\n\n-   araçlara\n\ndoğrudan erişilemez.\n\nÖnce:\n\n-   veraset ve intikal işlemleri yapılır\n\n-   vergi hesaplanır\n\n-   vergi ödemesi başlar\n\n-   ardından miras paylaşımı gerçekleşir.\n\n**Vergi işlemleri tamamlanmadan miras fiilen kullanılamaz.** Bu durum\nözellikle yüksek tutarlı miraslarda ciddi nakit sıkıntısı yaratabilir.\n\n**12. Hayat Sigortalarının İntikal Avantajı**\n\nHayat sigortası ödemesi miras sürecine girmeden doğrudan lehtara ödenir.\n\nAvantajları:\n\n-   hızlı ödeme,\n\n-   aileye nakit destek,\n\n-   miras sürecini beklememe.\n\n**13. Sağlık Sigortalarında Vergi Avantajı**\n\nÖzel sağlık sigortası ve tamamlayıcı sağlık sigortası primleri de\nmatrahtan düşülebilir.\n\nBu nedenle müşteri:\n\n\"Sigortaya ödediğim primin bir kısmını zaten vergi olarak ödeyecektim.\"\n\nşeklinde düşünmelidir.\n\n**14. BES ve Hayat Sigortasının Karşılaştırılması**\n\n**BES**\n\n-   Uzun vadeli birikim sağlar.\n\n-   Devlet katkısı vardır.\n\n-   Emeklilik geliri oluşturur.\n\n**Hayat Sigortası**\n\n-   Risk gerçekleştiğinde ödeme sağlar.\n\n-   Aileyi korur.\n\n-   Borç güvenliği sağlar.\n\nDoğru planlama her iki ürünü birlikte kullanmaktır.\n\n> **15. Yüksek Gelir Grubuna Vergi Planlaması Nasıl Anlatılır?**\n\nYüksek gelirli kişiler:\n\n-   yüksek vergi öder,\n\n-   yaşam standartlarını korumak ister,\n\n-   ailelerinin geleceğini güvence altına almak ister.\n\nDanışmanın anlatması gereken:\n\n\"Vergi zaten ödüyorsunuz; bunun bir kısmını ailenizi ve geleceğinizi\nkoruyacak çözümlere yönlendirebilirsiniz.\"\n\n=== BÖLÜM: SİGORTACILIKTA EN YAYGIN 15 YANLIŞ İNANIŞ VE SİGORTA SATIŞININ PSİKOLOJİSİ ===\n\n**5) SİGORTACILIKTA EN YAYGIN 15 YANLIŞ İNANIŞ**\n\nSigorta sektörü, hakkında en fazla yanlış bilginin dolaştığı alanlardan\nbiridir. En sık karşılaşılan yanlış inanışlar şunlardır:\n\n**1) \"Sigorta şirketleri ödeme yapmamak için bahane arar.\"**\n\nOysa sigorta şirketleri sözleşmede yazan teminatlar kapsamında ödeme\nyapar. Ödeme yapılmayan durumlar genellikle teminat dışı kalan\nrisklerdir.\n\n**2) \"Sigorta gereksiz bir masraftır.\"**\n\nSigorta masraf değil, olası büyük zararları küçük maliyetlerle yönetme\nyöntemidir.\n\n**3) \"Benim başıma gelmez.\"**\n\nRisk kişiye göre değil, olasılığa göre oluşur. Risk herkes için vardır.\n\n**4) \"Kaskom var, her şeyi karşılar.\"**\n\nHer poliçede teminat kapsamı farklıdır. Her zarar otomatik olarak\nkarşılanmaz.\n\n**5) \"Trafik sigortası kendi aracımı da karşılar.\"**\n\nZorunlu trafik sigortası karşı tarafın zararını karşılar, kendi\naracınızı değil.\n\n**6) \"Sigorta yaptırdıysam her durumda para alırım.\"**\n\nSigorta kazanç sağlama sistemi değil, zarar telafi sistemidir.\n\n**7) \"Sigorta pahalıdır.\"**\n\nSigorta pahalı değil, sigortasız kalmanın sonucu pahalıdır.\n\n**8) \"Hasar bildirirsem seneye poliçem iptal olur.\"**\n\nGenelde poliçe iptal edilmez; sadece hasarsızlık indirimi etkilenebilir.\n\n**9) \"Ev sahibiysem konut sigortasına gerek yok.\"**\n\nKonut sigortası sadece kiracılar için değildir; ev sahibi için daha\nönemlidir.\n\n**10) \"Küçük hasarları da mutlaka sigortadan almak gerekir.\"**\n\nBazen küçük hasar bildirimi, ileride prim artışına neden olabilir.\n\n**11) \"Sigorta yaptırdıktan sonra poliçeyi okumaya gerek yok.\"**\n\nPoliçenin kapsamını bilmemek, yanlış beklentilere yol açar.\n\n**12) \"Aynı şeyi iki şirketten sigortalarsam iki ödeme alırım.\"**\n\nSigorta kazanç sağlama aracı değildir; zarar kadar ödeme yapılır.\n\n**13) \"Sağlıklıyım, sağlık sigortasına ihtiyacım yok.\"**\n\nSigorta en çok sağlıklıyken yapılır; hastalık ortaya çıktıktan sonra\nteminat sınırlı olur.\n\n**14) \"Sigortacı sadece poliçe satan kişidir.\"**\n\nSigorta danışmanı, müşterinin risklerini analiz eden ve çözüm sunan\nkişidir.\n\n**15) \"Sigorta ihtiyacı zarar yaşandıktan sonra anlaşılır.\"**\n\nDoğru yaklaşım, risk oluşmadan önce güvence almaktır.\n\n**Sigorta Satmak Neden Zordur?**\n\n**İyi Sigorta Danışmanı Nasıl Fark Yaratır?**\n\nSigortacılık satış tarafında en zor sektörlerden biridir. Bunun sebebi\nürünün yapısından ve insan psikolojisinden kaynaklanır.\n\nStajyerlerin sektöre başlarken şu gerçeği bilmesi gerekir:\n\nSigortacılık, ürün değil güven satılan bir meslektir.\n\n**Sigorta Satışı Neden Zordur?**\n\n**1) Satılan Ürün Somut Değildir**\n\nSigortada müşteri:\n\n-   arabayı görmez,\n\n-   telefonu eline almaz,\n\n-   ürünü kullanmaz.\n\nSatın aldığı şey:\n\n-   bir sözleşme,\n\n-   bir güvence,\n\n-   geleceğe yönelik bir vaattir.\n\nİnsanlar somut ürün satın almayı daha kolay kabul eder.\n\n**2) İnsanlar Riskleri Düşünmek İstemez**\n\nSigorta şu konuları hatırlatır:\n\n-   kaza,\n\n-   hastalık,\n\n-   deprem,\n\n-   yangın,\n\n-   ölüm,\n\n-   iş kaybı.\n\nÇoğu insan bu konuları düşünmek istemez.\n\nBu yüzden konuşmayı bile ertelemek ister.\n\n**3) Sigortanın Faydası Hemen Görülmez**\n\nTelefon alındığında hemen kullanılır.\\\nAraba alındığında hemen sürülür.\n\nAma sigortanın faydası:\n\n-   belki hiç kullanılmayacaktır,\n\n-   belki yıllar sonra ortaya çıkacaktır.\n\nBu da satın alma kararını zorlaştırır.\n\n**4) İnsanlar Sigortayı Gider Olarak Görür**\n\nBirçok müşteri:\n\n\"Her yıl para ödüyorum ama karşılığını görmüyorum.\" diye düşünür.\n\nOysa sigorta kullanılmadığında aslında görevini yerine getirmiştir:\nzarar oluşmamıştır.\n\n**5) Sektörde Geçmiş Kötü Deneyimler Vardır**\n\nYanlış poliçe satışı,\\\neksik bilgilendirme,\\\nsatış sonrası ilgisizlik,\n\nmüşteride güven kaybı oluşturmuştur.\n\nYeni danışman önce bu güveni yeniden kurmak zorundadır.\n\n**Peki İyi Sigorta Danışmanı Nasıl Fark Yaratır?**\n\nBaşarılı danışman sadece poliçe satmaz.\n\n**1) Ürün Değil, Risk Analizi Yapar**\n\nİyi danışman şunu sorar:\n\n-   Bu kişinin geliri neye bağlı?\n\n-   Ailesi hangi risklere açık?\n\n-   İşletmesinde hangi riskler var?\n\nSonra çözüm sunar.\n\n**2) Satış Sonrası İlgisini Kesmez**\n\nKötü danışman poliçeyi satar ve kaybolur.\n\nİyi danışman:\n\n-   hasar anında müşterinin yanında olur,\n\n-   süreci takip eder,\n\n-   destek sağlar.\n\nMüşteri en çok hasar anını hatırlar.\n\n**3) Müşteriye Korku Satmaz, Güvence Sunar**\n\nBaşarılı danışman:\n\n\"Ya deprem olursa?\" diyerek korku satmaz.\n\nŞöyle anlatır:\n\n\"Böyle bir durumda ekonomik olarak zarar görmemenizi sağlıyoruz.\"\n\n**4) Uzun Vadeli İlişki Kurar**\n\nSigorta tek seferlik satış değildir.\n\nMüşteri:\n\n-   araba değiştirir,\n\n-   ev alır,\n\n-   çocuk sahibi olur,\n\n-   iş kurar.\n\nİyi danışman müşterinin hayat yolculuğuna eşlik eder.\n\n**5) Güvenilirlik En Büyük Sermayedir**\n\nSigortada müşteri önce şunu satın alır:\n\nDanışmana güven.\n\nGüven oluşursa poliçe zaten gelir.\n\n**Eğitimde Verilecek Ana Mesaj**\n\nStajyerlere şu cümle özellikle vurgulanabilir:\n\nİyi sigortacı poliçe satmaz, müşterinin geleceğini güvence altına alır.";

const SISTEM_TALIMATI = `Sen WE Sigorta'nın WhatsApp asistanısın. Sana verilen, sigortacılık eğitimine yönelik 7 BÖLÜMLÜK genel bilgi dokümanına (sigortacılığın tarihçesi, temel kavramlar/terimler sözlüğü, hayat dışı/elementer sigortalar, hayat sigortaları, Bireysel Emeklilik Sistemi/BES, vergi sistemi, sık yanlış inanışlar) dayanarak, müşterinin GENEL sigortacılık sorusunu cevaplıyorsun.

KURALLAR:
- SADECE aşağıda verilen belge metnine dayanarak cevap ver. Belgede yer almayan hiçbir bilgiyi UYDURMA.
- Belge, virgülle ayrılmış "=== BÖLÜM: ... ===" başlıklarıyla 7 farklı konuya ayrılmıştır - sorunun hangi bölümle ilgili olduğunu sen belirle, gerekirse birden fazla bölümden bilgi birleştirerek cevap ver.
- Eğer sorunun cevabı belgede YOKSA veya belge yetersizse, başka hiçbir şey yazmadan TAM OLARAK şunu yaz: YANIT_YOK
- Bu belge GENEL sigortacılık bilgisidir - müşterinin KENDİ POLİÇESİNE/HESABINA özel bir soru sorması durumunda (örn. "benim poliçemde bu var mı", "primim ne zaman yenilenecek", "hangi ürünü satın almalıyım") bu belgeden cevap veremeyeceğini unutma - böyle bir soru gelirse YANIT_YOK yaz (fallback mesajı danışmana yönlendirecektir). Bu belge sadece GENEL eğitim/kavram sorularını (örn. "kasko ile trafik sigortası farkı ne", "BES nedir", "muafiyet ne demek", "hayat sigortasının vergi avantajı var mı") cevaplamak içindir.
- Eğer cevap belgede varsa: kısa, net, sıcak bir dille (WhatsApp mesajı gibi, 2-8 cümle) cevap ver. Gerekirse madde madde yazabilirsin ama uzatma - müşteri bir eğitim kitabı değil, kısa ve anlaşılır bir WhatsApp cevabı bekliyor.
- Emin olmadığın, belgede açıkça yazmayan bir şeyi asla kendi yorumunla tamamlama - böyle bir durumda YANIT_YOK yaz.
- Türkçe cevap ver.
- Müşteriye HER ZAMAN resmi/"siz"li dille hitap et (örn. "faydalanabilirsiniz", "belirtir misiniz") - asla "sen"li/samimi dile geçme, müşteri sana samimi yazsa bile.
- Cevabın sonunda, uygunsa (soru buna elverişliyse) kısaca ilgili bir WE Sigorta ürününü nazikçe hatırlatabilirsin (örn. "Dilerseniz size bu konuda bir teklif de hazırlayabiliriz.") ama bunu ZORLAMA, ısrarcı/satışçı bir dil kullanma.`;

// Musterinin sorusunu, birlesik genel bilgi belgesine dayanarak cevaplar.
// Belgede cevap yoksa (soru cok kisiye ozel, ya da belgeyle alakasizsa) ya
// da API kullanilamiyorsa (ANTHROPIC_API_KEY tanimli degil, API hata
// donuyor vb.) standart "danismaninizla gorusun" fallback mesajini dondurur
// - boylece musteri hicbir zaman cevapsiz/hata mesajiyla kalmaz. Cagiran
// taraf (conversationEngine.js), donen cevabin TAM OLARAK
// DANISMAN_YONLENDIRME_MESAJI olup olmadigini kontrol ederek "gercek bir
// cevap mi yoksa eslesme yok mu" ayrimini yapabilir (bkz. ASK_PRODUCT
// serbest metin islenmesi).
const DANISMAN_YONLENDIRME_MESAJI =
  "Bu konudaki detayı elimdeki bilgilerle net olarak cevaplayamıyorum 🙏 Bu konuyla ilgili danışmanınızla görüşmenizi öneririz, size en doğru bilgiyi onlar verecektir.";

async function soruyaCevapVer(soru) {
  const apiKey = process.env.ANTHROPIC_API_KEY;
  if (!apiKey) {
    console.error("Genel sigorta bilgisi soru-cevap: ANTHROPIC_API_KEY tanımlı değil - fallback mesajı dönülüyor.");
    return DANISMAN_YONLENDIRME_MESAJI;
  }

  const prompt =
    `${SISTEM_TALIMATI}\n\n--- BELGE BAŞLANGICI ---\n${GENEL_BILGI_METNI}\n--- BELGE SONU ---\n\n` +
    `Müşterinin sorusu: "${soru}"\n\nCevabın:`;

  try {
    const cevap = await mesajGonder(apiKey, prompt, { maxTokens: 700 });
    const temiz = (cevap || "").trim();
    if (!temiz || temiz === "YANIT_YOK" || temiz.startsWith("YANIT_YOK")) {
      return DANISMAN_YONLENDIRME_MESAJI;
    }
    return temiz;
  } catch (err) {
    console.error("Genel sigorta bilgisi soru-cevap API hatası:", err.message);
    return DANISMAN_YONLENDIRME_MESAJI;
  }
}

module.exports = { soruyaCevapVer, DANISMAN_YONLENDIRME_MESAJI };
